insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('cashflow', 'advanced', 'module', 'm01-cost-recovery', 1, 'psc_carryforward spends 80000000.00 USD of capex and 10000000.00 of opex in 2030 against 100000000.00 of revenue, yet the 2030 row reports taxable_income 27000000.00 and tax 13500000.00. Why is a year that ends 40500000.00 in the red taxed at all?', '["The engine writes the 80000000.00 off as depreciation over the field life, so only a small part of it reduces the 2030 base and the rest waits for later years.", "The base is revenue less royalty, and the 80000000.00 of capex only becomes deductible once the cost pool has been fully recovered through the cap.", "Under a PSC the base is the contractor''s profit oil, and capex is not a deduction but a debt the cost oil repays, so 27000000.00 is taxed whether or not 80000000.00 was spent.", "Tax is charged on the 36000000.00 of cost oil recovered in the year, because cost oil is income to the contractor and profit oil is shared before tax."]'::jsonb, 2, 'The joint venture reflex reads 2030 as a loss with no tax; the PSC prices the contractor''s half of profit oil, 27000000.00, the same in a capex year as in a year with none.'),
  ('cashflow', 'advanced', 'module', 'm01-cost-recovery', 2, 'At a cost oil cap of 0.400000 the engine''s applyPSC line recovers 36000000.00 on 100000000.00 of revenue. A reader expects 40000000.00. What did the reader take the cap against?', '["The gross revenue. The cap is a share of revenue after the 10000000.00 royalty, and 40 percent of what is left is 36000000.00.", "The pool. A cap of 0.400000 on an 80000000.00 pool would release 32000000.00, and the reader rounded up to the nearest tranche of profit oil.", "The revenue after royalty and after opex, which leaves 80000000.00 to share, and 40 percent of 80000000.00 recovers less than the engine reports.", "The contractor''s entitlement, which at a 50 percent profit share is half the revenue, so the reader doubled the cap to reach the field level figure."]'::jsonb, 0, 'A cap read off the gross gives a cost oil larger than 36000000.00 and a pool that clears too early, and the error repeats in every year the cap binds.'),
  ('cashflow', 'advanced', 'module', 'm01-cost-recovery', 3, 'Sweeping the cap on the one-year applyPSC case, cost recovered rises from 18000000.00 at 0.200000 to 80000000.00 at 1.000000 while tax falls from 18000000.00 to 2500000.00. Why does a higher cap lower the tax?', '["A higher cap accelerates the depreciation of the 80000000.00 of capex, and the larger write-off shrinks the taxable income in the year it is claimed.", "The cap is applied to the tax itself as well as to the cost pool, so the 50 percent rate is scaled down in proportion to the share of cost recovered.", "The royalty falls as the cap rises, because the 10 percent royalty is charged on revenue after cost oil, and the smaller royalty base drags the tax down with it.", "Cost oil comes out before profit oil is split, so every USD more recovered is a USD less of profit oil, and profit oil is the taxable base."]'::jsonb, 3, 'Each step of the cap moves cost recovered up and profit oil down by the same amount: 54000000.00 recovered leaves 18000000.00 of profit oil and 9000000.00 of tax at 0.600000.'),
  ('cashflow', 'advanced', 'module', 'm01-cost-recovery', 4, 'The one-year applyPSC case at the 0.4 cap is rerun with 30000000 brought forward from an earlier year. Cost recovered is still 36000000.00, profit oil still 27000000.00 and net still minus 30500000.00. What did the extra pool change?', '["The recovery rises to 66000000.00, because the cap is a share of the pool and a larger pool lets more cost oil out in the same year.", "Only the carried amount, from 44000000.00 to 74000000.00; a bigger pool does not recover faster, it waits.", "The profit oil, which is reduced by the brought-forward amount before the split so that the contractor''s tax falls while the cash is unchanged.", "The tax, because the brought-forward cost is deductible against the contractor''s profit oil in the year it arrives even though the cap refuses to recover it."]'::jsonb, 1, 'The cap is a ceiling on recovery per year, not on the pool, so 30000000 of extra cost changes nothing in the year except how much is carried out of it.'),
  ('cashflow', 'advanced', 'module', 'm01-cost-recovery', 5, 'AKATA under production sharing at a 30 percent cap carries 183771360.00 out of 2029 and 207346412.26 out of 2035. The field has produced for seven years and the pool is larger at the end than at the start. What is growing it?', '["The engine escalates the unrecovered balance at the 3 percent inflation rate for every year it is carried, so a pool that waits grows even if nothing is added to it.", "Each year''s opex enters the pool faster than the cap lets cost oil out of a declining revenue, so the pool never shrinks for long and the field stops with more unrecovered than it began with.", "The 45 percent profit share is deducted from cost recovered before it leaves the pool, so only part of each year''s recovery actually reduces the balance.", "The tax of 10393930.24 in 2035 is charged to the pool when the contractor cannot pay it from profit oil, and the late years add their tax to the balance."]'::jsonb, 1, 'Cost recovered falls from 50228640.00 in 2029 to 19797962.36 in 2035 while opex rises every year; the cap is a ceiling per year, and the years run out before the pool does.'),
  ('cashflow', 'advanced', 'module', 'm01-cost-recovery', 6, 'AKATA''s take is 82.1085 percent at a 60, an 80 and a 100 percent cap, while NPV reads 29960298.75, 42273746.33 and 48148675.31. Why does the take not follow the NPV?', '["The take is computed at the 60 percent cap for every run, because the engine reports take on the base case and only reruns the discounted lines when the cap changes.", "The take excludes cost oil, the only line the cap moves, so every cap that clears the pool gives one take by construction.", "The NPV differences come from the IRR of 19.8650, 32.2148 and 48.4048 percent, which the take does not use because it is a share of revenue rather than a rate of return.", "Once the pool clears inside the life the cap only moves timing, and take is a ratio of undiscounted totals that cannot see timing."]'::jsonb, 3, 'The pool clears in 2034 at 60 percent, in 2031 at 80 and in 2030 at 100; the same USD arrive sooner, and sooner is what NPV and IRR price and take does not.'),
  ('cashflow', 'advanced', 'module', 'm01-cost-recovery', 7, 'AKATA at a 30 percent cap reports a take of 120.4874 percent. What does a take above 100 percent mean on a PSC?', '["The state collected royalty and tax in every year while the contractor ended the field with 207346412.26 still unrecovered, and nothing bounds the ratio at 100.", "The engine has counted the 207346412.26 of unrecovered cost as government revenue, which is the error a cap that never clears produces in the take.", "The take is capped at 100 in the engine and any reading above it is a rounding artefact of the discounted take, which reads 90.1534 percent at the 60 percent cap.", "The working interest was applied twice, once at the door and once in the take, so the contractor''s share was counted against a ledger that had already been scaled."]'::jsonb, 0, 'The hand-derived case does the same at 101.0000 percent: the contractor ends 1000000.00 down and the state''s take is measured against a contractor that never got its money back.'),
  ('cashflow', 'advanced', 'module', 'm01-cost-recovery', 8, 'psc_tranches lifts 1000000.00 bbl in 2030, exactly the from_cum_mmbbl 1 boundary of its second tranche, yet the 2030 row prints a contractor share of 60.000000 and taxable_income 32400000.00. Why is 2030 not in the 40 percent tranche?', '["The boundary is exclusive: from_cum_mmbbl 1 means more than 1000000 bbl, and a field that reaches exactly 1000000 in 2030 has not passed it until it produces one barrel more.", "The engine blends the two shares across the barrels of the year, and with the whole of 2030 below the boundary the blend is 0.600000 until 2031 starts above it.", "The table is read at the cumulative liquids at the start of the year, which is 0 in 2030; the field crosses 1000000 bbl on its last barrel of 2030, too late to change 2030.", "The prior cumulative defaults to 0 and the engine reads the table on that default in every year until psc_prior_cumulative_liquids_bbl is set explicitly."]'::jsonb, 2, 'The tranche table read at 999999 bbl gives 0.600000 and at 1000000 gives 0.400000, so the boundary is not exclusive; it is the start-of-year reading that keeps 2030 at 60.'),
  ('cashflow', 'advanced', 'module', 'm01-cost-recovery', 9, 'psc_tranches_prior_cumulative keeps the first tranche row at 60 percent from 0, yet its 2030 taxable_income is 21600000.00 where psc_tranches printed 32400000.00. What changed 2030?', '["The third tranche at 30 percent from 2 pulls the average share of the field down, and the engine prices every year at the average of the tranches it will pass through.", "The 1500000 bbl of prior cumulative is added to the cost pool, so more cost oil is taken in 2030 and less profit oil is shared.", "The table is read at the end of 2030, when the cumulative is 2500000 bbl, and the 40 percent row applies at that reading.", "psc_prior_cumulative_liquids_bbl 1500000 opens 2030 inside the 40 percent tranche, so the first row of the table is never used."]'::jsonb, 3, 'A brownfield gets no fresh start: 2030 opens at 1500000 bbl and 2031 opens at 2500000, in the 30 percent tranche, giving taxable income 16200000.00 and an NPV of minus 12200000.00.'),
  ('cashflow', 'advanced', 'module', 'm01-cost-recovery', 10, 'psc_itc sets psc_itc_pct 50 on the 80000000.00 of capex. Both years print tax 0.00 while taxable_income stays 27000000.00. Why does the credit leave the base untouched?', '["The credit is applied after the tax is computed and offsets the tax itself, so the base of 27000000.00 is never reduced by it.", "The credit comes off the cost pool rather than the base, and a smaller pool recovers faster so the tax vanishes as cost oil.", "The taxable_income column is printed before the credit is deducted, and the base after the credit is 0.00 in both years, which is why the tax is 0.00.", "The credit is paid to the contractor as cash in 2030, and the engine reports it in the tax column as a negative tax that nets the 13500000.00 to zero."]'::jsonb, 0, 'The applyPSC sample says it in one call: an ITC of 40000000 against a tax before credit of 4500000.00 uses 4500000.00 and carries 35500000.00, and the base is not in the sentence.'),
  ('cashflow', 'advanced', 'module', 'm01-cost-recovery', 11, 'A credit larger than the tax it meets waits for the next year''s tax. What happens to the balance of psc_itc''s 40000000 credit that is still unused when the field ends in 2031?', '["It is refunded in the final row as a negative tax, which is why the 2031 net cash flow of 53000000.00 is higher than the 39500000.00 of the case without the credit.", "Nothing. There is no refund line and no KPI for the balance, and a field that ends with credit unused ends with nothing.", "It is added to unrecovered cost at cessation, since a credit the state owes is a cost and the pool holds unpaid cost.", "It is reported in the KPI block beside the take, so a reader sees how much of the 74.0000 percent was offset by credit."]'::jsonb, 1, 'The 2031 net of 53000000.00 is 39500000.00 plus the 13500000.00 of tax the credit absorbed in that year; the remainder carries past the end of the field and is never seen again.'),
  ('cashflow', 'advanced', 'module', 'm01-cost-recovery', 12, 'psc_wi_50 reports total oil 1000000.00 bbl for a field that lifted 1000000 bbl in each of 2030 and 2031, and the rows carry oil_bbl 500000.00. Why has the volume halved with the money?', '["The engine halves the volumes because the cap binds in both years, and a binding cap converts half of the barrels into cost oil that is not counted as production.", "The production file was pre-scaled to 50 percent before upload, and the engine reads the halved barrels as the field''s production.", "Under a PSC the working interest is applied at the door, so the rows are the contractor''s share and the volumes are entitlement volumes, not field volumes.", "The oil_bbl column reports the barrels behind the contractor''s profit oil, and at a 50 percent profit share that is half the field''s production."]'::jsonb, 2, 'The joint venture ledger keeps field revenue and field volumes and applies the share later; the PSC ledger scales everything first, which is why NPV halves to minus 2295454.55 and take stays 101.0000.'),
  ('cashflow', 'advanced', 'module', 'm01-cost-recovery', 13, 'psc_sinking_fund adds abandonment_cost_usd 10000000 funded from 2031. The 2031 row shows decom_fund_contribution 10000000.00, net cash flow 29500000.00 against 39500000.00, and tax still 13500000.00. Where did the contribution go?', '["Into the recoverable cost lane, so it rides the pool as a cost to be recovered rather than being paid outside the contract.", "It was deducted from the contractor''s profit oil before tax, which is why the net fell by the full 10000000.00 while the taxable income stayed at 27000000.00.", "It was paid from the contractor''s profit oil after tax and shared with the state at the 50 percent profit split, leaving the contractor''s cash lower by the whole sum.", "It was charged as a lump sum in the last year of the field, and the sinking fund label only records that the money was set aside in 2031 rather than spent."]'::jsonb, 0, 'The tax is unchanged at 13500000.00 because the base is unchanged; the contribution is a cost, and costs under a PSC go into the pool, not into the tax base.'),
  ('cashflow', 'advanced', 'module', 'm01-cost-recovery', 14, 'psc_abandonment_wi_50 charges a 10000000.00 lump sum against the 50 percent working interest flows. The 2031 net is 9750000.00 where psc_wi_50 had 19750000.00. What does the difference say about the lump sum?', '["It was scaled to 5000000.00 and the other 5000000.00 is the tax on the abandonment, which the engine charges at the 50 percent rate on the lump sum.", "It was scaled to 5000000.00 and then discounted at 10 percent back to 2030 before being charged, which is why the row moves by twice the scaled amount.", "It was charged in full because the working interest only applies to revenue and volumes, and the capex of 40000000.00 in 2030 was likewise charged unscaled.", "It was charged in full: the lump sum is not scaled by the working interest, and the whole 10000000.00 came off a ledger that had already been halved."]'::jsonb, 3, 'The capex in 2030 halved to 40000000.00 with everything else; the abandonment did not, and NPV reads minus 11386363.64 against minus 2295454.55 without it.'),
  ('cashflow', 'advanced', 'module', 'm01-cost-recovery', 15, 'AKATA under production sharing at a 30 percent cap leaves 207346412.26 in the pool at the end of 2035. Which output column of the engine reports that figure?', '["The depreciation column, which under a PSC reports the unrecovered capex in the pool rather than a write-off, because cost oil replaces depreciation.", "None. The rows carry no cost recovered and no carried forward column, the KPI block prints unrecovered cost at cessation not reported, and the pool is read only by marching applyPSC over the engine''s own rows.", "The cumulative_cash_flow column, which on a PSC row is the contractor''s cumulative position after cost oil and therefore mirrors the pool with its sign reversed.", "The tax column, because tax is the only line that moves with the pool, 10393930.24 in 2035 at 30 percent against 8400589.37 at 60, and the pool is recoverable from it."]'::jsonb, 1, 'Tax does move with the pool, but a reader who has not marched the pool cannot tell a low tax from a low profit, and the NPV of minus 104151944.05 does not say why either.'),
  ('cashflow', 'advanced', 'module', 'm02-the-pia-royalties', 1, 'AKATA under the PIA is shallow water and its 2029 production royalty is 22944240.00 on 186032000.00 of gross revenue. A reader applying 0.125000 to the gross does not land on that figure. What did the reader miss?', '["The price royalty of 3605512.362941, which the engine folds into the production royalty column before reporting the row.", "The gas. The 0.125000 is charged on the oil and a separate gas royalty of 0.070000 on the gas, and the row is the sum of the two.", "The HCDT, which is deducted from gross revenue before the royalty rate is applied so that the royalty base is smaller than the gross.", "The water depth of 60 m, which places AKATA in a reduced shallow water band below the 0.125000 that a 100 m field pays."]'::jsonb, 1, 'Onshore the same row reads 27454240.00 with the oil at 0.150000 and the gas still at 0.070000; the gas rate has its own table and its own terrain reading.'),
  ('cashflow', 'advanced', 'module', 'm02-the-pia-royalties', 2, 'pia_deep_offshore_full lifts 21900000 bbl in 2025, 60000 bopd, and pays 131400000.00 of production royalty on 1752000000.00 of gross revenue. A reader prices the first 50000 bopd at 0.050000 and only the barrels above at 0.075000 and gets a smaller figure. What is wrong with the reader''s method?', '["The reader has the threshold wrong: deep offshore steps at 50001 bopd, and at 60000 bopd the whole of the first 50001 bopd is charged at 0.050000 and only the rest at 0.075000.", "The reader has the tiers reversed: the first 50000 bopd of a deep offshore field pay 0.075000 and the barrels above the threshold pay the lower 0.050000 tier.", "The reader should have blended the two rates across the twelve months of 2025 and then applied the average to the year, since the engine prices the year on its monthly rates.", "Deep offshore steps once at 50000 bopd and the rate that applies to the year applies to the whole year; the blend exists in the marginal field terrain alone."]'::jsonb, 3, 'pia_deep_offshore_naive_30k halves the volume to 10950000 bbl, under the threshold, and pays 43800000.00 on 876000000.00, 0.050000 of every barrel; there is no barrel priced at the other rate in either case.'),
  ('cashflow', 'advanced', 'module', 'm02-the-pia-royalties', 3, 'The worked example and pia_deep_offshore_full both carry pia_water_depth_m 100, and one pays a production royalty rate of 0.125000 while the other pays 0.075000. What does deriveOilRoyaltyRate read?', '["The terrain string and the daily rate. It does not read the water depth, the licence type, the lease status or the price.", "The water depth, and 100 m sits on the boundary between the shallow water and deep offshore bands so the engine falls back to the terrain string to break the tie.", "The licence type, since a PML pays the shallow water rate and the deep offshore case is on a different licence.", "The oil price, which moves the field between the 0.125000 and 0.075000 tiers because the price royalty and the production royalty share one curve."]'::jsonb, 0, 'The rate is chosen by a string somebody typed; the depth is carried in the config and never consulted, and the licence type moves the hydrocarbon tax rate, not this one.'),
  ('cashflow', 'advanced', 'module', 'm02-the-pia-royalties', 4, 'AKATA''s total royalties read 143184623.40 onshore, 122393644.64 as shallow water and 59501441.00 as deep offshore, with NPV 36246417.05, 42943268.01 and 141623594.88. Which of the NPV moves is due to the royalty alone?', '["Both moves. The terrain string changes only the royalty table, and every other line in the cascade follows from the royalty through the tax bases.", "Shallow water to deep offshore. The onshore move also raises the NDDC levy to the onshore rate, so it is not a pure royalty change.", "Onshore to shallow water. The deep offshore move under the conservative reading also zeroes the hydrocarbon tax; the aggressive reading keeps the same 59501441.00 of royalties and gives NPV 61725382.46.", "Neither. Each terrain also changes the gas royalty, 0.070000 onshore and shallow water against 0.050000 deep offshore, so no move is oil royalty alone."]'::jsonb, 2, 'The same 59501441.00 of royalties gives NPV 141623594.88 or 61725382.46 depending on a reading of the hydrocarbon tax; the royalty explains the first move and only part of the second.'),
  ('cashflow', 'advanced', 'module', 'm02-the-pia-royalties', 5, 'deriveOilRoyaltyRate for a marginal field reads 0.050000 at 5000 bopd, 0.062500 at 10000 and 0.106250 at 20000. Why is the 10000 bopd rate exactly halfway between the first two tiers while the 20000 bopd rate is not halfway to 0.150000?', '["The 10000 bopd row is an interpolation between two table entries and the 20000 row is a table entry, so only the first is an average.", "At 10000 bopd the year''s barrels split evenly between the 5 percent and 7.5 percent tiers; at 20000 bopd half the barrels sit in the 15 percent tier and the other half are still priced at the two lower tiers.", "The blend is arithmetic below 10000 bopd and geometric above it, which is why the upper rows rise more slowly than a straight average would.", "The 20000 bopd rate is capped by the deep offshore step at 50000 bopd, so the marginal curve is bent toward 0.132500 rather than toward 0.150000."]'::jsonb, 1, 'The rate is the average across the year''s barrels, so the first 10000 bopd are always priced at the two lower tiers and the rate approaches 0.150000 from below, 0.142708 at 120000 bopd.'),
  ('cashflow', 'advanced', 'module', 'm02-the-pia-royalties', 6, 'AKATA as a marginal field pays a 2029 production royalty of 10182990.00 against 22944240.00 as shallow water, yet its 2029 HCT is 29251153.65 against 25422778.65 and total tax rises to 223261390.90. Why did the tax rise when the royalty fell?', '["The marginal field terrain carries a hydrocarbon tax rate of its own, higher than shallow water, which the engine applies whenever the blended royalty is used, so the blend and the rate move together.", "The price royalty is charged at a higher rate on a marginal field and is added into the HCT base rather than deducted from it, which lifts the tax.", "The marginal terrain forfeits the production allowance, and the 5500000.00 that shallow water deducts from the base is charged in full on a marginal field.", "pia_marginal_field_pre_2021 was not set, so the field pays 30 percent on a base that the smaller royalty has left larger; the blend does not switch the tax rate."]'::jsonb, 3, 'pia_marginal_field_blend has the flag true and pays 0.150000, 26361776.50 on 175745176.68; AKATA marginal pays 0.300000 and NPV is 61154067.34, with the tax taking back most of the royalty saved.'),
  ('cashflow', 'advanced', 'module', 'm02-the-pia-royalties', 7, 'The PIA worked example sells at 80.000000 in 2025 and pays a price royalty of 34905145.759897 on 1460000000.00 of gross revenue, the 0.023908 in the table, where the 2021 curve reads 0.030000 at 80. What lowered the rate?', '["The anchor prices escalate at 2 percent a year from 2021, so the same nominal price sits lower on the curve every year.", "The rate is applied to revenue after the production royalty of 182500000.00 rather than to the gross, and the smaller base shows up as a smaller apparent rate.", "The price is deflated by the 3 percent inflation before the curve is read, so the real price of 2025 is below 80 and earns the lower rate.", "The twelve monthly rows of 2025 are each read on the curve and averaged, and the monthly reads fall below the annual read because the curve is convex."]'::jsonb, 0, 'At 60 USD/bbl the rate is 0.010000 in 2021, 0.005431 in 2025 and 0.000205 in 2030; a flat price is a falling royalty because the anchors move under it.'),
  ('cashflow', 'advanced', 'module', 'm02-the-pia-royalties', 8, 'In 2035 a price of 60 USD/bbl reads a price royalty rate of 0.000000, and in 2026 a price of 55 already does. What has happened to the curve?', '["The engine floors the rate at 0.000000 whenever the price is below the year''s applied oil price, and 60 is below every escalated price in the deck.", "The lower tier has been switched off by the 2025 framework change, which removed the price royalty below the 100 anchor for every terrain.", "The 50 anchor, escalating at 2 percent a year from 2021, has moved past those prices, and below the first anchor the rate is nothing.", "The rate is rounded to six decimals, and by 2035 the true rate at 60 is a small positive number that rounds to zero."]'::jsonb, 2, 'At 60 the rate is 0.010000 in 2021, 0.005431 in 2025, 0.000205 in 2030 and 0.000000 in 2035, a royalty in name only long before it vanishes.'),
  ('cashflow', 'advanced', 'module', 'm02-the-pia-royalties', 9, 'pia_price_royalty_ceiling at 200.000000 pays 365000000.000000 on 3650000000.00 of gross revenue, exactly 10 percent, and the table reads 0.100000 at 200 in 2021, 2025, 2030 and 2035. What does a price above the 150 anchor earn?', '["A rate that keeps climbing at the upper tier''s slope, twice as steep as the lower tier, so that 200 earns more than 150 and 250 more than 200.", "The upper tier rate read at the escalated 150 anchor, which drifts upward with the years so that 200 earns a little more each year.", "A rate of 0.100000 plus the lower tier rate at 100, because the tiers stack and a price that has passed both anchors pays both.", "The ceiling of 0.100000 and no more, which is the only part of the curve that the years do not erode."]'::jsonb, 3, 'pia_high_price_royalty_tiers at 140.000000 pays 202709508.889684 on 2555000000.00, still between the escalated 100 and 150 anchors; 160 and 200 both read 0.100000 in 2021.'),
  ('cashflow', 'advanced', 'module', 'm02-the-pia-royalties', 10, 'pia_gas_only_hct_zero sells 20000000.00 Mscf and no oil for 90000000.00 of gross revenue at an oil price of 80.000000, and its price_royalty column reads 0.000000 beside a production royalty of 6300000.00. Why no price royalty?', '["The price royalty reads the oil price and charges the oil; there is no oil, and gas does not carry it.", "The gas price of 4.5 USD per Mscf is far below the 50 anchor, and the engine reads the price royalty curve at the gas price for a gas field.", "The oil price of 80.000000 in 2025 reads 0.000000 on the curve because the 50 anchor has escalated past it by 2025.", "The field is treated as frontier when it has no oil, and frontier is exempt from the price royalty outright."]'::jsonb, 0, 'The 6300000.00 is 0.070000 on the gas; the price royalty on a field with gas is charged on the oil revenue alone, not on the gross, which is the second common mistake.'),
  ('cashflow', 'advanced', 'module', 'm02-the-pia-royalties', 11, 'pia_frontier_exempt prints a production royalty of 21900000.00 on 292000000.00 of gross revenue and a price royalty of 0.000000, at a price of 80.000000 in 2025. What two things does the frontier terrain do to the royalties?', '["It steps the production royalty from 0.050000 to 0.075000 at 50000 bopd like deep offshore and defers the price royalty until the field reaches that threshold.", "It fixes the production royalty at 0.075000 at every daily rate, and it exempts the field from the price royalty outright, 0.000000 even at 200 USD/bbl.", "It blends the production royalty across three tiers like a marginal field and reads the price royalty at the 2021 anchors without escalation.", "It fixes the production royalty at 0.075000 and caps the price royalty at the 0.100000 ceiling, which at 80.000000 in 2025 happens to round to 0.000000."]'::jsonb, 1, 'pia_onshore_new_lease on the same 292000000.00 of revenue pays 43800000.00 of production royalty and 6981029.151979 of price royalty; the frontier string removes half of one and all of the other.'),
  ('cashflow', 'advanced', 'module', 'm02-the-pia-royalties', 12, 'pia_deep_offshore_wi_50 and pia_deep_offshore_naive_30k both carry oil_bbl 10950000.00 on the 2025 row, yet the first pays 65700000.00 of production royalty and the second 43800000.00. Why do two rows with the same barrels pay different royalties?', '["The WI 50 row adds its price royalty of 20943087.455938 into the production royalty column, and the naive row reports the same price royalty separately.", "The naive row is read at 2025 anchors and the WI 50 row at 2021 anchors, because a working interest below 100 percent fixes the curve at the year the licence was granted.", "The tier is read on the field''s barrels and the working interest is applied to the money afterward; the WI 50 row is still a 60000 bopd field at 0.075000, while the naive upload made a 30000 bopd field at 0.050000.", "The WI 50 row applies 0.075000 to the field''s 21900000.00 bbl and then halves, while the naive row applies 0.050000 to the full 21900000.00 and does not halve, and the two scalings happen to land on those figures."]'::jsonb, 2, 'cumulative_oil_bbl_lifetime reads 21900000.00 on the WI 50 row and 10950000.00 on the naive row; only that column and prod_alw_eligible_bbl remember the field.'),
  ('cashflow', 'advanced', 'module', 'm02-the-pia-royalties', 13, 'pia_deep_offshore_naive_30k lands in the cheaper 0.050000 tier yet reports NPV 372530915.97, below the correct half share of 445282165.97. What pulls it down?', '["It still bears the full 100000000.00 of capex, 100000000.00 of opex, 5100000.00 of HCDT and 15000000.00 of NDDC against half the revenue; two errors in opposite directions, and neither cancels the other.", "The lower tier lowers the royalty but the hydrocarbon tax rises to take back the difference, since deep offshore under the conservative reading charges HCT on the royalty saved.", "The engine detects the pre-scaled upload and charges a penalty royalty at the 0.075000 rate on the barrels it infers were left out of the file.", "The naive row is discounted one extra year because the halved production is read as starting in 2026, and the extra division by 1.1 costs the difference."]'::jsonb, 0, 'The take reads 44.8919 percent against 42.6183 for both honest runs; the naive row is a different field with the wrong costs, not a share of the real one.'),
  ('cashflow', 'advanced', 'module', 'm02-the-pia-royalties', 14, 'AKATA under the PIA at pia_working_interest_pct 50 reports NPV 21471634.00, exactly half of 42943268.01, and a take of 75.6789 percent that has not moved. Under joint venture terms the same field''s take rises from 66.1723 percent at WI 100 to 79.7034 at WI 60. Why does one take move and the other not?', '["The PIA take is computed before the working interest is applied and the JV take after it, so only the JV ratio can see the partners'' share.", "The PIA royalties are field-level tiers that do not scale with the working interest, so the state''s share stays the same fraction of a smaller revenue.", "The JV take includes the partners'' royalty and tax at their own rates, which are higher than the operator''s, so a smaller working interest raises the blended rate.", "The PIA scales the whole ledger, so every line the ratio reads is halved together; the JV rows keep field-level revenue and count the partners'' share as take."]'::jsonb, 3, 'PIA royalties halve to 61196822.32 and the allowance to 2750000.00 while the eligible barrels stay 2200000.00; the ratio of two halved numbers is the number it was.'),
  ('cashflow', 'advanced', 'module', 'm02-the-pia-royalties', 15, 'A production file has been pre-scaled to the operator''s share before upload. What can the engine report to warn the reader?', '["A working_interest_pct of 50 inferred from the ratio of the uploaded barrels to the lifetime cumulative, which it prints in the KPI block as a warning.", "Nothing. It cannot tell a pre-scaled upload from a small field: the naive run reports working_interest_pct not reported exactly as the full run does.", "A prod_alw_cap_applied flag of true on the first row, because a halved field reaches the wrong tier and the engine marks any tier it cannot reconcile.", "An ingestion refusal, since the volume columns of a pre-scaled file fail the per-well naming check that the production loader applies."]'::jsonb, 1, 'The row''s oil_bbl is the entitlement either way; the only honest scaling is pia_working_interest_pct on the full field, which keeps cumulative_oil_bbl_lifetime at 21900000.00.'),
  ('cashflow', 'advanced', 'module', 'm03-hydrocarbon-tax', 1, 'AKATA under the PIA prints hcdt 0.00 in 2029, 720000.00 in 2030 and 741600.00 in 2031, with opex 24000000.00, 24720000.00 and 25461600.00 in those years. Which opex is each levy computed on?', '["The current year''s, at 3 percent, with the first year exempt under the host community rules because the field has no community agreement until production starts.", "The current year''s, but the levy is paid a year in arrears, so the 720000.00 charged on 2029''s opex appears in the 2030 row as cash rather than as a liability.", "The prior year''s. pia_prior_year_opex_usd is 0, so 2029 pays none; 2030 reads 3 percent of 2029''s 24000000.00 and 2031 reads 2030''s 24720000.00.", "A fixed sum that the engine escalates at the opex escalator, which is why the levy grows by the same 3 percent a year as the opex does."]'::jsonb, 2, 'The levy lags the cost by a year, and the first year of a new field pays none unless somebody supplies a prior year; with pia_prior_year_opex_usd 20000000 the 2029 row reads 600000.00.'),
  ('cashflow', 'advanced', 'module', 'm03-hydrocarbon-tax', 2, 'The worked example prints nddc 15000000.00 on opex of 182500000.00 while pia_onshore_new_lease prints 900000.00 on opex of 30000000.00. Both carry pia_nddc_levy_pct_of_opex 3. What makes the first one so large?', '["pia_nddc_levy_fixed_usd 15000000 is set on the worked example, and a fixed sum replaces the percentage whatever the opex is.", "The worked example reads the levy on the prior year''s opex of 170000000, and 3 percent of that is 5100000.00, which the engine then grosses up for the deductible NDDC.", "The worked example is shallow water and the NDDC is charged on shallow water opex at a higher rate than the 3 percent that applies onshore.", "The worked example''s opex is uploaded as twelve monthly rows and the levy is charged on each row at 3 percent and then summed twelve times over."]'::jsonb, 0, 'A 3 percent field with no opex pays none, but the fixed sum is a flat 15000000.00 in every year regardless of opex; on AKATA, with no fixed sum, hcdt and nddc read the same 720000.00 and 741600.00 one year apart.'),
  ('cashflow', 'advanced', 'module', 'm03-hydrocarbon-tax', 3, 'pia_prior_year_opex_zero removes the 5100000.00 HCDT from the worked example. Both tax bases rise by exactly 5100000.00, HCT rises from 284810956.27 to 286340956.27, and NPV rises from 135185570.34 to 137098070.34, less than the levy saved. Why less?', '["The NPV is on the real basis, and the 5100000.00 saved in 2025 money is deflated by the 3 percent inflation before it reaches the NPV.", "The levy is deductible from both bases, so removing it raises HCT, CIT and TET, and the extra taxes take back part of the 5100000.00.", "The levy is only partly removed: the engine keeps a minimum HCDT on the current year''s opex when the prior year is zero, and that minimum still costs cash.", "The 5100000.00 comes back as a deferred CPR cost, which the cap defers to a later year that the one-year field does not have."]'::jsonb, 1, 'Removing the levy raised both bases by the levy, and the CIT base sits 15000000.00 below the HCT base in both rows because NDDC is deducted for CIT and not for HCT.'),
  ('cashflow', 'advanced', 'module', 'm03-hydrocarbon-tax', 4, 'On the worked example cit_assessable_profit is 1039994854.24 and hct_assessable_profit is 1054994854.24, a gap of exactly 15000000.00. What sits in that gap?', '["The production allowance, which is deducted from the HCT base and not from the CIT base, and on this case the allowance is 45625000.00 before the price cap.", "The HCDT of 5100000.00 together with the TET of 25999871.36, which are deducted for CIT because they are levies and not for HCT because they are taxes.", "One year of the capital allowance on the 300000000.00 of capex, which CIT deducts at the assessable stage and HCT deducts one stage later.", "The NDDC, which is deducted for CIT and not for HCT, and 15000000.00 is the fixed NDDC."]'::jsonb, 3, 'The allowance comes off later: hct_assessable_profit less 60000000.00 of capital allowance less 45625000.00 of production allowance is hct_chargeable_profit 949369854.24.'),
  ('cashflow', 'advanced', 'module', 'm03-hydrocarbon-tax', 5, 'The worked example''s CPR cap is swept from 30 to 100 percent and cpr_costs_claimed stays 242500000.00 and NPV stays 135185570.34 at every setting. What does the sweep show about the cap?', '["The cap is a share of revenue, 438000000.00 even at 30 percent, and it does nothing while the claim of 242500000.00 sits below it.", "The cap is a share of the costs, and a cap that ranges from 30 to 100 percent of 242500000.00 is always satisfied by claiming the whole 242500000.00.", "The cap only acts on new leases, and the worked example is a converted lease so the CPR limit is read but never applied.", "The cap acts on the deferred pool from earlier years and the worked example, having one year, has no pool for the cap to bind on."]'::jsonb, 0, 'The cap only exists where costs approach revenue: on AKATA in 2032 the cap is 75826707.47 against opex 26225448.00 plus 51000000.00 of allowance, and 1398740.53 defers.'),
  ('cashflow', 'advanced', 'module', 'm03-hydrocarbon-tax', 6, 'cpr_forfeiture has a cpr_cap of 52000000.00, claims 52000000.00, defers 8000000.00 and prints hct_loss_carryforward 0.00. The field has no later year. What is the 8000000.00?', '["A tax loss carried forward at the HCT rate, which the engine reports in cpr_deferred_to_next rather than in the loss column because it arose from the cap.", "A capital allowance the engine will claim in the next recovery year of the five, since the cap defers the allowance and not the opex.", "A deferred cost that is not a tax loss and does not survive cessation; the KPI block reports CPR forfeited at cessation 8000000.00.", "A cost that earns interest at the discount rate while it waits, so that the 8000000.00 grows to a larger claim in whichever year the cap next allows it."]'::jsonb, 2, 'pia_cpr_carry_two_years adds 22000000.00 to the deferred pool in every year and forfeits 66000000.00 at cessation while hct_loss_carryforward reads 0.00 on every row; a deferral is not a loss.'),
  ('cashflow', 'advanced', 'module', 'm03-hydrocarbon-tax', 7, 'AKATA at a CPR limit of 65 percent defers 1398740.53 in 2032 and 14561618.62 in 2033, then clears in 2034. At a limit of 40 percent HCT rises from 77020493.72 to 107354738.83 and NPV falls from 42943268.01 to minus 1723561.25. Why does a tighter cap hurt a declining field so much?', '["A tighter cap lengthens the capex recovery from five years to more, and the allowance that is pushed past 2035 is never claimed.", "The cap is a share of a shrinking revenue while the costs are not shrinking, so more is deferred each year and what is still deferred when the field stops is lost.", "The cap at 40 percent is read on the costs rather than on the revenue, and 40 percent of the costs is far less than 65 percent of them.", "The deferred costs become tax losses, and losses under the PIA are relieved at a lower rate than the 30 percent HCT that the costs would have offset."]'::jsonb, 1, 'In 2032 the cap is 75826707.47 against opex 26225448.00 and 51000000.00 of allowance; in 2034 the cap is 55829921.49 and the claim 51384196.40. The cap on a declining field is a tax on the decline.'),
  ('cashflow', 'advanced', 'module', 'm03-hydrocarbon-tax', 8, 'computeProductionAllowance on a converted lease at 10 USD/bbl returns 2000000.00 on 1000000 bbl with cap applied false, where the same barrels at 80 USD/bbl return 2500000.00. What does the false flag report?', '["That no cap acted, so the 2000000.00 is the converted rate of 2.5 USD/bbl reduced by a rounding of the price to the nearest 10 USD.", "That the price cap was tested and did not bind, because at 10 USD/bbl the 20 percent limit is 2 USD/bbl, which is the converted rate after the price adjustment.", "That the field is a converted lease and the volume cap can never apply, so the flag is always false and the 2000000.00 is the new lease rate at 20 percent of price.", "Only the volume cap. The 20 percent of price limit has bound and reduced the allowance, and the flag is silent about it."]'::jsonb, 3, 'At 12.5 USD/bbl the two rules meet and the allowance is 2500000.00 either way; a reader who reads false as no cap reports 2500000.00 where the engine prints 2000000.00.'),
  ('cashflow', 'advanced', 'module', 'm03-hydrocarbon-tax', 9, 'A new shallow water lease with 1000000 bbl in the year earns 8000000.00 from a prior cumulative of 99000000, 4000000.00 on 500000.00 eligible bbl from 99500000, and 0.00 from 100000000. How is the cap read?', '["On lifetime barrels against pia_new_lease_prod_alw_cap_shallow_bbl 100000000, and the year that crosses the cap is split at the barrel that crosses it.", "On the year''s own barrels, so any year that lifts more than the remaining headroom loses the whole allowance for that year.", "On the prior cumulative alone, so a field that starts the year under 100000000 keeps the full 8000000.00 whatever it lifts in the year.", "On the price, since 8 USD/bbl is 10 percent of 80 and the 20 percent of price limit leaves headroom that shrinks as the cumulative rises."]'::jsonb, 0, 'allowance_cap_midyear lifts 2000000.00 bbl from a prior 99000000 and reports prod_alw_eligible_bbl 1000000.00, allowance 8000000.00, cap applied true and cumulative_oil_bbl_lifetime 101000000.00; the 2026 row earns 0.00.'),
  ('cashflow', 'advanced', 'module', 'm03-hydrocarbon-tax', 10, 'AKATA as a new lease from a prior cumulative of 0 and from a prior cumulative of 96000000 print identical 2029 rows, allowance 17600000.00 on 2200000.00 eligible bbl with the flag false, yet the life totals are 77440000.00 and 32000000.00 and NPV 55961597.02 against 46233118.46. Why is the first row identical?', '["The engine reads the prior cumulative only from the second year onward, so the first row of every new lease is priced as if the field were fresh.", "The 2029 row earns the allowance on the price cap alone, 20 percent of 82.000000, and the volume cap is only tested once the price cap stops binding.", "The cap has not yet been reached in 2029; it is read on lifetime barrels, and it is the later years that lose the allowance, so only the totals show the difference.", "The flag false on both rows means the volume cap was disabled for the run, and the difference in totals comes from the shorter recovery period of the second case."]'::jsonb, 2, 'At 96000000 prior the field passes 100000000 inside the life, and from that barrel on the eligible count is 0.00; HCT reads 74680493.72 against 61048493.72 with no cap.'),
  ('cashflow', 'advanced', 'module', 'm03-hydrocarbon-tax', 11, 'pia_gas_only_hct_zero sells 20000000.00 Mscf and no liquids for 90000000.00. hct_assessable_profit is 0.00 and hct_tax 0.00, while CIT is 14880000.00 on cit_chargeable_profit 49600000.00. Why is one profit tax charged and not the other?', '["The HCT rate is 0.000000 for a gas field under the conservative deep offshore reading, and the engine applies that reading to any field without oil.", "The production allowance on a gas field takes the HCT base to zero, while CIT, which has no allowance, is still charged.", "The HCT is charged only above the minimum effective tax rate of 15 percent, and CIT at 30 percent already satisfies it on a gas field.", "The HCT base is oil and condensate; gas is left out unless pia_hct_include_gas_revenue is opened, while the CIT base includes gas."]'::jsonb, 3, 'With the hatch open the base is rebuilt on the whole revenue, hct_assessable_profit 68600000.00, hct_tax 19380000.00, and NPV falls from 17380000.00 to minus 2000000.00.'),
  ('cashflow', 'advanced', 'module', 'm03-hydrocarbon-tax', 12, 'On the worked example''s chargeable profit of 949369854.24 the HCT is 284810956.27 on a PML and 142405478.14 on a PPL, and the NPV moves from 135185570.34 to 277591048.48. What moved the tax?', '["The PPL halves the production allowance and the capital allowance together, which halves the chargeable profit and therefore the tax charged on it.", "The licence type alone: deriveHctRate reads 0.300000 for a shallow water PML converted lease and 0.150000 for a PPL, on the same base.", "The PPL moves the field from the 2021 Act to the 2025 framework, and the framework switch halves the hydrocarbon tax rate.", "The PPL is read as a new lease, and the 8 USD/bbl allowance takes the base down to half of the converted lease figure."]'::jsonb, 1, 'The framework does not move HCT: AKATA under force_pia reports the same 77020493.72 as under nta_2025. The licence moves take from 86.1703 percent to 71.6019 with nothing else changed.'),
  ('cashflow', 'advanced', 'module', 'm03-hydrocarbon-tax', 13, 'pia_deep_offshore_full pays HCT 0.00 and reports NPV 890564331.93; the same field reads HCT 419659147.53 under pia_deep_offshore_nta_aggressive with NPV 449025977.03, and 174857978.14 under the custom 12.5 with NPV 693827146.42. What decides which one is right?', '["Nothing in the engine. pia_deep_offshore_hct_interpretation is a string somebody chose, and conservative_zero is a default, not a finding.", "The water depth: pia_water_depth_m 100 is the boundary at which the engine switches from the conservative reading to the aggressive one.", "The framework date trigger: a base year of 2025 selects the 2021 Act and the conservative reading, and a later base year selects the aggressive one automatically.", "The licence: a PML pays the aggressive 0.300000 and a PPL the custom rate, so the string is only a label for what the licence already decided."]'::jsonb, 0, 'On AKATA the same choice is NPV 141623594.88 against 61725382.46, a larger move than the oil price sweep from 82 to 120, which reaches 128984232.18.'),
  ('cashflow', 'advanced', 'module', 'm03-hydrocarbon-tax', 14, 'cpr_forfeiture has cit_assessable_profit 7987389.27 and its recoverable costs would take the base below zero. The engine reports cit_chargeable_profit 2662463.09 and cit_tax 798738.93. What became of the allowance that was not used?', '["It became the 8000000.00 in cpr_deferred_to_next, which is the same disallowed allowance reported under the CPR label rather than the CIT one.", "It was carried to the HCT computation on the same row, which is why the HCT base of 8487389.27 is higher than the CIT base.", "It was lost. The engine restricts the allowance to two thirds of the assessable profit and carries nothing: cit_loss_carryforward reads 0.00, where the Act carries the disallowed amount.", "It was carried as a CIT loss to the next year at the 30 percent rate, and the field, having no next year, shows the loss as 0.00 at cessation."]'::jsonb, 2, 'The chargeable profit is exactly one third of 7987389.27 because two thirds is the most the allowance may take; the 8000000.00 deferral is the CPR cap, a different rule on a different line.'),
  ('cashflow', 'advanced', 'module', 'm03-hydrocarbon-tax', 15, 'On the one-year worked example, pia_capex_recovery_years 1 claims 482500000.00 and gives NPV 279185570.34, while 10 claims 212500000.00 and gives NPV 117185570.34. What does the setting decide on a field that stops before its recovery years run out?', '["The timing only, because the unclaimed allowance is carried to the cessation year and claimed there in a single final deduction.", "How much of the 300000000.00 is ever claimed: one year claims all of it, ten years claim a tenth, and the rest is never claimed at all.", "The rate at which the deferred CPR pool is released, since the recovery years set the cap on cost claims and not the capital allowance.", "Whether the two thirds restriction binds, since a faster recovery lifts the allowance above two thirds of a thin profit in the first year."]'::jsonb, 1, 'At 5 years the claim is 242500000.00 and NPV 135185570.34; on AKATA the second year''s 45000000.00 of capex starts its own five-year recovery, and a field that stops early leaves its allowance unclaimed.'),
  ('cashflow', 'advanced', 'module', 'm04-levies-and-losses', 1, 'On the published PIA worked example the tertiary education tax is 25999871.36 under pia_only and the development levy is 41599794.17 under nta_2025, and the digest calls the levy 1.6 x TET. What makes the ratio exactly the ratio of the rates?', '["The levy is charged on the HCT assessable profit of 1054994854.24, which is larger than the CIT base by the fixed NDDC, and the extra base happens to match the rate change.", "Both are charged on the same line, the CIT assessable profit of 1039994854.24, so only the rates differ, 4 against 2.5.", "The levy is charged on the chargeable profit of 979994854.24 after the two-thirds restriction and then grossed up by the restriction, which returns the ratio of the rates.", "The levy includes the TET it replaces, so the 4 percent is the old TET with a surcharge stacked on the same base."]'::jsonb, 1, 'Royalty 217405145.76, HCT 284810956.27 and CIT 293998456.27 are identical in both runs; only the last line changes, and total tax moves from 604809283.90 to 620409206.71.'),
  ('cashflow', 'advanced', 'module', 'm04-levies-and-losses', 2, 'A reader who knows the 2021 Act and has heard of the 2025 framework adds TET and the development levy to the same year of AKATA. What does the ledger say about that total?', '["No run of the engine produces it: one of tet_tax and dev_levy_tax is 0.00 on every row, and the fiscal_framework column says which one was charged.", "It is right for AKATA, whose 2029 base year sits on the trigger, so the engine charges TET of 3369056.19 under the Act and a levy of 5390489.91 under the framework in the same year.", "It is right whenever the override is set to auto, because auto blends the two frameworks in proportion to the years each one covers.", "It overstates by the TET only in the years after 2026, since the levy replaces TET from the switch date and the earlier rows keep both."]'::jsonb, 0, 'AKATA on auto pays a levy of 5390489.91 in 2029 and 21007007.79 over the life with TET at 0.00; forced to pia_only it pays TET of 3369056.19 and no levy.'),
  ('cashflow', 'advanced', 'module', 'm04-levies-and-losses', 3, 'On pia_loss_relief the 2026 TET is 5755415.35 whether the 2025 CIT loss of 12056305.36 is relieved or clamped. Why does the pool never reach the levy?', '["The pool was already spent against the 2025 HCT of 508108.39, so nothing was left for 2026 to relieve against any base at all.", "The TET is charged on the HCT base, which never went into loss, so a CIT pool has no base to meet on the levy line.", "The clamp only deletes losses on the JV cascade; under the PIA the pool is relieved against every tax on the row including the levy.", "Relief acts on the chargeable profit and the levy sits on the assessable profit, a line the pool is never subtracted from."]'::jsonb, 3, 'The 2026 CIT is 59448092.62 relieved against 63064984.23 clamped, while HCT 63814984.23 and TET 5755415.35 are the same in both runs.'),
  ('cashflow', 'advanced', 'module', 'm04-levies-and-losses', 4, 'A PIA ledger has a base year of 2027 and no value for pia_under_nta_2025_override at all. Which framework do its rows print?', '["pia_only, because with no override the engine has no instruction to leave the 2021 Act and keeps the framework it was written for.", "The engine refuses the run, since the framework is a required string and the decision table has no row for an unset override.", "nta_2025, because an unset override behaves as auto and the date trigger selects the 2025 framework from 2026 onward.", "nta_2025 for the rows from 2027 and pia_only for any earlier rows the upload carries, because the trigger is read on each row''s year."]'::jsonb, 2, 'The decision table reads base 2027 with the override unset as nta_2025, beside base 2025 auto as pia_only and base 2030 force_pia as pia_only.'),
  ('cashflow', 'advanced', 'module', 'm04-levies-and-losses', 5, 'pia_loss_relief has a 2025 base year with rows in 2025 and 2026, and its 2026 row prints pia_only with TET 5755415.35 and a development levy of 0.00. Why did the 2026 row not switch?', '["The framework is chosen once from the base year and every row inherits it; the row year is never read.", "The 2026 row is still inside the transition year, and the engine only switches a row that falls after the base year plus one.", "The loss pool of 12056305.36 carried into 2026 pins the row to the framework the loss was banked under, so relief and framework travel together.", "The engine switched the rate but kept the column name, so the 5755415.35 is a levy at 4 percent printed under the TET heading."]'::jsonb, 0, 'The same holds on pia_cpr_carry_two_years, whose 2025 to 2027 rows all print pia_only, and on elt_pia_multiyear from 2025 to 2030.'),
  ('cashflow', 'advanced', 'module', 'm04-levies-and-losses', 6, 'The worked example at a 2025 base year forced to nta_2025 pays a levy of 41599794.17 with NPV 119585647.53; the same volumes at a 2026 base year on auto pay 41684425.66 with NPV 120347330.91. The framework is nta_2025 both times. What moved the levy?', '["The 3 percent inflation rate deflated the 2026 base year once more, lifting the real profit on which the levy is charged.", "The price royalty anchors escalated a year further, so the price royalty fell from 34905145.759897 to 32789358.588134 and the assessable profit the levy follows rose to 1042110641.41.", "The levy rate steps up in its second year under the framework, which is why the later ledger pays a little more at the same base.", "The 2026 run discounts one year less, and the levy is reported on the discounted profit rather than the row''s nominal one."]'::jsonb, 1, 'Total royalty fell from 217405145.76 to 215289358.59, and HCT rose from 284810956.27 to 285445692.42 and CIT from 293998456.27 to 294633192.42 on the same movement.'),
  ('cashflow', 'advanced', 'module', 'm04-levies-and-losses', 7, 'jv_loss_carryforward''s 2031 row reads taxable income 65000000.00 and tax 30000000.00, which is not 50 percent of the column. A reader concludes the rate is wrong. What did the reader miss?', '["The depreciation of 5000000.00 in 2031 was deducted a second time from the tax rather than from the income, which is how the engine relieves a loss year.", "The 2030 loss reduced the rate for the following year from 50 to 40 percent, since relief in this engine works on the rate and not on the base.", "The pool is applied after the taxable income column: loss_offset_used reads 5000000.00 and the rate is charged on the remainder.", "The royalty of 20000000.00 is credited against tax under joint venture terms, and the credit happens to be 2500000.00 after discounting."]'::jsonb, 2, 'The pool of 5000000.00 banked in 2030 falls to 0.00 in 2031; net cash flow is 40000000.00 and NPV -13636363.64 against -15909090.91 with the clamp on.'),
  ('cashflow', 'advanced', 'module', 'm04-levies-and-losses', 8, 'The engine''s single-year function is given taxable income of 10000000.00 at the 50 percent rate with a pool of 15000000.00 brought forward. What does it report?', '["Offset used 15000000.00, tax 0.00 and a negative taxable income of 5000000.00 banked as a fresh loss for the next year.", "Offset used 10000000.00, tax 0.00 and a pool after of 0.00, because a pool is spent whole in the first year with income.", "Offset used 5000000.00, tax 2500000.00 and a pool after of 10000000.00, because the offset is capped at half the year''s income.", "Offset used 10000000.00, tax 0.00 and a pool after of 5000000.00."]'::jsonb, 3, 'The offset is capped at the year''s taxable income, so tax bottoms at 0.00 and the rest waits: a pool of 40000000.00 leaves 30000000.00 after the same year.'),
  ('cashflow', 'advanced', 'module', 'm04-levies-and-losses', 9, 'With apply_loss_carryforward set to false, what happens to the 5000000.00 loss of jv_loss_carryforward''s 2030 row?', '["It is deferred until the ledger ends and then reported as tax losses unused at cessation, so NPV is unchanged and the memo line carries it.", "It is deleted: loss_carryforward reads 0.00, 2031 pays the full 32500000.00 and NPV falls to -15909090.91.", "It is relieved against the HCT base instead of the CIT base, which is why the 2031 tax does not move.", "It is carried at face value but charged interest at the discount rate, so the 2031 offset is worth less than 5000000.00."]'::jsonb, 1, 'The clamp does not defer the loss; the IRR moves from -20.0000 to -25.0000 percent because 2500000.00 of tax that relief would have removed is paid.'),
  ('cashflow', 'advanced', 'module', 'm04-levies-and-losses', 10, 'On pia_loss_relief the 2026 HCT of 63814984.23 is the same with relief on and off while the CIT is 59448092.62 relieved against 63064984.23 clamped. Why does relief touch one tax and not the other?', '["The pools are kept per base: 2025''s HCT chargeable profit stayed positive at 1693694.64, so no HCT pool existed, while the CIT base was -12056305.36 and banked a pool.", "HCT is charged on liquids and the loss arose on gas, so the pool is a gas pool that only the CIT base, which includes gas, can absorb.", "The HCT pool was used first against the 2025 HCT of 508108.39 and exhausted, leaving only the CIT pool to reach 2026.", "The engine relieves the larger tax last, and the CIT pool of 12056305.36 was exhausted before the HCT line was reached."]'::jsonb, 0, 'An HCT profit cannot absorb a CIT loss; the two are reported apart as hct_loss_carryforward and cit_loss_carryforward, and NPV moves from -8763295.32 clamped to -5475212.04 relieved.'),
  ('cashflow', 'advanced', 'module', 'm04-levies-and-losses', 11, 'jv_loss_unused_at_cessation reports NPV -50000000.00 and tax losses unused at cessation of 5000000.00. What is the unused pool worth in the NPV?', '["2500000.00, the tax it would save at the 50 percent rate, which the engine has already netted into the -50000000.00.", "5000000.00 discounted one year, since the pool is carried to the year after cessation and valued there.", "Nothing: it is a memo line outside the NPV, a shield with nothing to shield, and adding it back counts a year the ledger does not contain.", "2500000.00 in present value only if the reader adds it by hand, which the engine invites by printing the memo line beside the KPIs."]'::jsonb, 2, 'Give the same capex one more year of production, as jv_loss_carryforward does, and the pool is spent: tax falls from 32500000.00 to 30000000.00 and the memo line disappears.'),
  ('cashflow', 'advanced', 'module', 'm04-levies-and-losses', 12, 'Each regime names the value the horizon left behind differently. Which regime prints no cessation memo at all?', '["Joint venture, which banks the loss in the row''s loss_carryforward column and therefore has no separate memo to print.", "Production sharing: unrecovered cost at cessation is not reported, and the pool can only be read by marching the cost recovery function over the rows.", "The PIA, whose deferred CPR balance is relieved against the final year''s CIT and so never reaches cessation.", "None of them: the JV prints tax losses unused, the PIA prints CPR forfeited and the PSC prints the unrecovered pool at cessation."]'::jsonb, 1, 'cpr_forfeiture ends with CPR forfeited at cessation 8000000.00 and jv_loss_unused_at_cessation with tax losses unused 5000000.00; the PSC pool of 207346412.26 on AKATA at a 30 percent cap appears in no output.'),
  ('cashflow', 'advanced', 'module', 'm04-levies-and-losses', 13, 'With pia_apply_minimum_etr true at 85 percent the worked example grows a min_etr_topup column reading 279186342.20 and total tax becomes 883995626.10. Which taxes count as already paid when the floor is measured?', '["HCT and CIT alone, 284810956.27 and 293998456.27, since the floor is a floor on the profit taxes and royalty is not a tax on profit.", "All of them: the 604809283.90 the floor is measured against includes royalty and the levies.", "Only the taxes charged on the chargeable profit of 979994854.24, which is the profit the 85 percent is applied to and the only line a rate can be measured on.", "HCT, CIT and TET, but not royalty, since royalty is charged on revenue rather than on profit."]'::jsonb, 3, 'The top-up is 85 percent of the CIT assessable profit of 1039994854.24 less the 604809283.90 in the tax column, and that column is HCT 284810956.27 plus CIT 293998456.27 plus TET 25999871.36; royalty 217405145.76, HCDT and NDDC sit outside it, and against HCT plus CIT alone the shortfall would come out larger than 279186342.20.'),
  ('cashflow', 'advanced', 'module', 'm04-levies-and-losses', 14, 'At 15 percent the floor does not bind on the worked example. What does the row show for min_etr_topup?', '["Nothing: the column exists only where the floor was charged, and the KPI line reads min ETR top-up not reported.", "A value of 0.00, printed so that a reader can confirm the floor was tested and found already satisfied.", "The shortfall as a negative number, the amount by which 604809283.90 exceeds 15 percent of 1039994854.24.", "The 15 percent of the assessable profit of 1039994854.24, printed as the floor tested, with a flag beside it reading false because it did not bind."]'::jsonb, 0, 'The default for pia_apply_minimum_etr is false and every other published PIA case runs with it off; when it binds at 85 percent the column appears with 279186342.20.'),
  ('cashflow', 'advanced', 'module', 'm04-levies-and-losses', 15, 'The 85 percent run turns the worked example''s net cash flow of 135185570.34 into -144000771.86 and its take of 86.1703 percent into 114.7315. How can a take exceed 100 percent?', '["It cannot; a take above 100 percent is a display fault in the KPI line, and the 114.7315 should be read as 100 with the excess carried to the next year.", "The take ratio counts the 300000000.00 of capex as government revenue once the floor binds, since capex recovery is suspended under a minimum rate.", "The top-up is charged on a profit measured before capex, so it can exceed the cash the year generates, and the engine refuses to cap it at the year''s cash.", "The floor is measured on the chargeable profit of 979994854.24 while take is measured on the assessable one, and the two denominators differ by enough to push the ratio past 100."]'::jsonb, 2, 'Payback moves from Year 0 to beyond project life and DPI from 0.450619 to -0.480003; the government collected more than the year''s pre-take value.'),
  ('cashflow', 'advanced', 'module', 'm05-end-of-life', 1, 'elt_royalty_tail''s 2031 row would sell 120000.00 bbl at 100.000000 USD against opex of 10000000.00, and with the limit on the ledger ends at 2030. Why was a year whose gross revenue exceeds its opex trimmed?', '["The test is net cash flow, and the 5000000.00 of depreciation the year would carry turns its operating margin into a loss.", "The test is taxable income after the loss offset, and the 2031 row would have banked a loss with no year after it to spend it.", "The test is revenue less royalty against opex, and after the 20 percent royalty the year falls short of 10000000.00.", "The test is cumulative cash flow, still -12500000.00 at the end of 2030 and not yet positive in 2031."]'::jsonb, 2, 'Tax, depreciation and capex play no part; the KPI line reads economic_limit_year 2030 with years trimmed 1, and NPV is -12500000.00 on the one row that remains.'),
  ('cashflow', 'advanced', 'module', 'm05-end-of-life', 2, 'A reader runs elt_off_tail_kept without touching apply_economic_limit and reads NPV 13987603.31 and IRR 173.0447 percent. What did the default decide?', '["To keep the 2032 row: a net cash flow of -9200000.00, a 14200000.00 loss nothing will spend, and a KPI line reading economic_limit_year not reported.", "To trim the 2032 row and report the trimmed NPV, since a year selling 10000.00 bbl against 10000000.00 of opex fails the test whether or not the flag is set.", "To keep the row but exclude it from the NPV, so 13987603.31 is the value of the two producing years alone.", "To test the row on taxable income rather than operating margin, which -14200000.00 fails, and to trim it on that basis."]'::jsonb, 0, 'With apply_economic_limit true the row goes and the KPIs read NPV 21590909.09, IRR 200.0000 percent, economic_limit_year 2031, rows 2.'),
  ('cashflow', 'advanced', 'module', 'm05-end-of-life', 3, 'AKATA extended to 2041 reads revenue less royalty against opex of 37795328.32 against 31314556.41 in 2038 and 31541919.46 against 32253993.10 in 2039. What does the engine report as economic_limit_year?', '["2039, the first year that fails, which is where the ledger is cut so that the failing year is the one recorded.", "2038, the last year that passes; 2039 fails and it and the two years after it are trimmed.", "2041, because the limit is read on the cumulative margin and the field as a whole never fails it.", "2037, because the test requires a year to pass by a margin and 2038 passes by too little to count."]'::jsonb, 1, 'Limit on: 10 rows ending in 2038, years trimmed 3, NPV 93890737.45 against 87727489.23 with the tail kept; a reader who reports 2039 has kept a losing year.'),
  ('cashflow', 'advanced', 'module', 'm05-end-of-life', 4, 'abandonment_final_year adds a 10000000.00 lump sum to the 2031 row: net cash flow falls from 37500000.00 to 27500000.00 while tax stays 32500000.00 and taxable income 65000000.00. Why did the tax not move?', '["The engine deducted it and then added back the same 10000000.00 as depreciation recapture, so the two cancel on the tax line.", "The lump sum is deductible but only against the loss pool, and the pool was empty in 2031, so the deduction waits for a year that never comes.", "The cost is deducted from the following year''s taxable income, and 2031 is the last modeled year, so the deduction was never reached.", "The outflow is charged after the cascade has finished; the engine refuses to deduct the lump sum from any base."]'::jsonb, 3, 'Total tax on every abandonment case equals the total without abandonment, 65000000.00 on the two-year case and 148425219.46 on AKATA; NPV falls from 21590909.09 to 12500000.00, the lump sum discounted one year.'),
  ('cashflow', 'advanced', 'module', 'm05-end-of-life', 5, 'With abandonment_year 2033 on the two-year case the engine appends a row with no revenue, depreciation of 5000000.00 and a net cash flow of -10000000.00, and NPV is 14077761.08 against 12500000.00 with the cost in 2031. What is the appended row doing?', '["Paying later, which is cheaper on present value, and banking a loss of 5000000.00 that nothing will use.", "Earning two more years of price escalation, which lifts the 2033 row above the 2031 one.", "Spreading the 10000000.00 across 2032 and 2033 as two half payments, so each is discounted more lightly than the whole.", "Relieving the abandonment cost against the depreciation of 5000000.00, which is why NPV rises rather than falls."]'::jsonb, 0, 'The 2033 flow discounts to -7513148.01 against -10000000.00 undiscounted; IRR is 170.4159 percent against 120.0000 with the cost in 2031.'),
  ('cashflow', 'advanced', 'module', 'm05-end-of-life', 6, 'AKATA at a 100 percent working interest with a 60000000 lump sum reports IRR 23.2570 percent; at 50 percent the same entry reports 12.7634 percent and NPV 2398979.53. What should the 50 percent partner have entered?', '["The same 60000000, because the engine scales every monetary line by the working interest, and 12.7634 percent is the honest half-share reading.", "The cost net of tax relief, since the partner''s share of the deduction is what the engine expects in the abandonment column.", "The share of the cost, because the lump sum is charged in full against the share flows and the engine will not scale it.", "Twice the cost, so that the engine''s halving returns the field-level 60000000 the partner is jointly liable for."]'::jsonb, 2, 'jv_abandonment_wi_60 shows the mechanism: royalty 12000000.00 and tax 19500000.00 are the share, the abandonment_cost column reads 10000000.00, and half the field now carries the whole bill.'),
  ('cashflow', 'advanced', 'module', 'm05-end-of-life', 7, 'jv_sinking_fund funds the same 10000000.00 as two contributions of 5000000.00 and reports NPV 16818181.82 against the lump sum''s 12500000.00. Where does the gain come from?', '["The fund earns interest at the 10 percent discount rate inside the engine, and the accumulated balance exceeds the 10000000.00 it has to pay, so the surplus is released to the contractor in the final year.", "The contributions are charged after tax like the lump sum, but splitting the outflow across two years discounts the second half more gently, and that discounting difference alone accounts for the whole gain.", "The fund is discounted at the real rate while the lump sum is discounted at the nominal one, and the difference between 6.796117 and 10.000000 percent applied to 10000000.00 is the gain reported.", "The contribution rides the opex lane, so taxable income falls to 60000000.00 and tax to 30000000.00 a year, and the final spend is paid from the fund with no further outflow."]'::jsonb, 3, 'Total tax is 60000000.00 against 65000000.00, the 2031 row prints abandonment_cost_funded 10000000.00, and IRR is 133.3333 against 120.0000 percent.'),
  ('cashflow', 'advanced', 'module', 'm05-end-of-life', 8, 'pia_sinking_fund contributes 30000000.00 in its single year: HCT falls from 284810956.27 to 275810956.27 and CIT from 293998456.27 to 284998456.27. What happens to the TET of 25999871.36?', '["It falls by 2.5 percent of 30000000.00, since the levy sits on the assessable profit that the contribution reduces.", "Nothing: the contribution relieves the two profit taxes at their rates and the engine refuses to relieve the levies.", "It falls in proportion to CIT, because the levy is a fixed fraction of the CIT paid and moves with it.", "It rises, because a lower HCT leaves more assessable profit for the levy to be charged on."]'::jsonb, 1, 'NPV falls from 135185570.34 to 123185570.34 and the unit technical cost rises from 26.438356 to 28.082192 USD per boe; the levy line is unchanged.'),
  ('cashflow', 'advanced', 'module', 'm05-end-of-life', 9, 'On AKATA a fund from 2029 reports NPV 44902775.54 and IRR 21.9086 percent, a fund from 2032 reports 47415100.31 and 23.9820, and the lump sum in 2035 reports 38666394.86 and 23.2570. Why do NPV and IRR rank the early fund differently?', '["Money moved out of the early years hurts a rate more than a present value, so the early fund beats the lump sum on NPV and loses to it on IRR, and neither is wrong.", "The early fund''s seven contributions of 8571428.57 are discounted at the real rate while its IRR is computed on the nominal flows, so the two readings use different money.", "The IRR of the early fund is one root of two, and the engine reported the lower one; read at the other root the early fund wins on both.", "The early fund relieves the most tax, 124585925.52 in total, and tax relief raises NPV but is excluded from the IRR vector."]'::jsonb, 0, 'Starting in 2032 pays four contributions of 15000000.00 and gives the higher NPV because the money leaves later; both funds beat the lump sum on NPV.'),
  ('cashflow', 'advanced', 'module', 'm05-end-of-life', 10, 'pia_sinking_fund_wi_50 reports total fund contributions of 15000000.00 while total_abandonment_cost and abandonment_cost_funded read 30000000.00. Was the fund underfunded?', '["Yes: the fund collected half the cost, so the remaining 15000000.00 was charged as a lump sum in the final row and NPV fell to 61592785.17.", "No: the contribution was halved with the other monetary lines and the cost it funds was not, and the engine refuses to reconcile the two.", "Yes: the working interest scaled the contributions but the field still had to pay 30000000.00, and the shortfall is the reason the unit technical cost rose to 29.726027.", "No: the 30000000.00 is the field-level cost printed for reference, and the engine funded it from the partner''s 15000000.00 plus the other partner''s unreported share, which the KPI line nets out."]'::jsonb, 1, 'Under a fund the share paid the contributions; under a lump sum it paid the whole number. On AKATA at 50 percent the fund''s IRR stays 21.9086 percent while the lump sum''s falls to 12.7634.'),
  ('cashflow', 'advanced', 'module', 'm05-end-of-life', 11, 'schedule_shift_1 keeps 50000000.00 of capex in 2030 while production and opex reappear in 2031 and 2032, and NPV is 17355371.90. What does schedule_shift_years move?', '["Everything in the ledger, capex included, so the project as a whole starts a year later and every row keeps its relation to the others.", "Production only; opex stays in 2030 as a standing cost, which is why the 2030 row shows a loss of 5000000.00.", "Production and opex only; capex stays where it was, so the delay is a delay of first oil against a spend already made.", "Production, opex and the base year together, so that the escalators restart from the year of first oil."]'::jsonb, 2, 'The 2030 row reads revenue 0.00, depreciation 5000000.00, a loss carried forward of 5000000.00 and net cash flow -50000000.00; 2031 spends the pool and pays 30000000.00.'),
  ('cashflow', 'advanced', 'module', 'm05-end-of-life', 12, 'AKATA delayed one year sells its first 2200000.00 bbl in 2030 at 83.640000 rather than 82.000000 and pays opex of 24720000.00 rather than 24000000.00. Why are first-year values not first-year values?', '["The escalators count calendar years from the base year and do not care when first oil came; the engine refuses to hold prices or opex at first-oil levels.", "The engine escalates the delayed year twice, once for the shift and once for the calendar, which is why both price and opex moved by a full step.", "The delayed first year inherits the second year''s price and opex because the row list was shifted as a block and the labels were left behind.", "Inflation of 3 percent was applied to the first production year because a delay converts the real basis to a nominal one."]'::jsonb, 0, 'The delayed first year reports 55541846.40 against 31746007.20 at zero shift, where the same barrels had to carry the 210000000.00 of capex; NPV is 56565094.12 against 72534830.66.'),
  ('cashflow', 'advanced', 'module', 'm05-end-of-life', 13, 'AKATA at a three-year shift lists rows for 2029, 2030 and 2032 onward with no 2031 row. NPV fell from 40880824.32 at two years to 17894126.42, yet IRR rose from 14.6753 to 15.1070 percent and payback shortened from 4.96 to 4.90 years. Which readings can be trusted?', '["The IRR and payback, which are computed on the flows as listed; the NPV is the one that double-discounted the empty year and fell too far.", "All three, because a longer wait can raise a rate of return when the later rows carry escalated prices of 87.019056 and beyond and the capex is a year further behind them.", "None of them, because a ledger with a missing calendar year is refused by the engine and the KPIs printed are those of the two-year run carried forward unchanged.", "The NPV, which is discounted on calendar years; IRR and payback are counted on rows, so the missing row made the delay look a year shorter to them."]'::jsonb, 3, 'A longer wait for the same money cannot raise a rate of return; the engine refuses to emit a row for an empty year or to report the gap anywhere but the row list.'),
  ('cashflow', 'advanced', 'module', 'm05-end-of-life', 14, 'A reader sees 72513070.98 on AKATA''s profile at the applied rate and 72534830.66 in the headline, assumes one is stale and reruns. What is the gap of -21759.68?', '["A rounding of the flows to two decimals before the profile is summed, which loses a few cents on every row across seven years.", "The profile point is evaluated at the applied rate rounded to two decimals, 6.8, while the headline sits at 6.796117 percent; 6.8 is past the rate and NPV falls with rate.", "The half-year shift of mid-year discounting, which the profile applies and the headline does not.", "The 2029 row, which the headline discounts at exponent zero and the profile at exponent one."]'::jsonb, 1, 'The engine''s own npv() at the exact rate returns 72534830.66; on the nominal basis the point matches the headline exactly, 21590909.09 against 21590909.09 on jv_analytic_decision_kpis.'),
  ('cashflow', 'advanced', 'module', 'm05-end-of-life', 15, 'The vector [-100, 208, -108.12] has NPV zero at 2.0000 percent and at 6.0000 percent. The engine reports 6.0000. Why that root?', '["The engine reports the larger root by rule, because an IRR is the highest rate at which the project is still worth doing.", "The engine reports the root nearest zero on the positive side, and 6.0000 is the one that satisfies that rule after the bisection fallback.", "Newton starts from 10 percent and reaches the root nearer 10; the header does not say which root is returned when there are several.", "The engine averages the two roots and rounds to the nearest whole percent, which lands on 6.0000."]'::jsonb, 2, 'Terminal negatives are where the shape comes from: AKATA with a 60000000 lump sum ends on -29598201.95 and reports 23.2570 percent; with 200000000 it ends on -169598201.95, reports null, and its NPV is negative at every sampled rate.'),
  ('cashflow', 'advanced', 'module', 'm06-the-expert-reading', 1, 'AKATA under the PIA pays a development levy of 5390489.91 in 2029. Which line of the row is it charged on?', '["The CIT assessable profit of 134762247.64, before the two-thirds restriction.", "The CIT chargeable profit of 92762247.64, after the capital allowance has been taken off, since a levy follows the tax it accompanies.", "The HCT chargeable profit of 84742595.49, because the levy replaced the TET that the 2021 Act charged on the hydrocarbon tax base.", "The gross revenue of 186032000.00, at a rate blended with the royalty, which is why it moves with the terrain string."]'::jsonb, 0, 'Five taxes on three bases: the levy at 4 percent of 134762247.64 is 5390489.91, and the row''s TET is 0.00 because the base year 2029 selects nta_2025.'),
  ('cashflow', 'advanced', 'module', 'm06-the-expert-reading', 2, 'AKATA under production sharing at a 60 percent cost oil cap reports NPV 29960298.75, and its pool reads 133542720.00 at the end of 2029 and 0.00 by 2034. Where does a reader get those pool figures?', '["From the taxable_income column, which under a PSC is the unrecovered cost carried into the year.", "From the KPI block, which reports unrecovered cost at cessation whenever the cap binds in the final year.", "Only by marching the cost recovery function over the rows the engine produced; no row and no KPI carries the pool.", "From the difference between gross revenue and net cash flow on each row, which is the cost oil taken that year."]'::jsonb, 2, 'At a 30 percent cap the pool ends at 207346412.26 and no KPI mentions it; the rows report royalty, profit oil as taxable income, tax and net cash flow.'),
  ('cashflow', 'advanced', 'module', 'm06-the-expert-reading', 3, 'Which terrain''s oil royalty rate changes with the daily rate as a single step rather than a blend?', '["The marginal field, whose rate is 0.050000 to 5000 bopd and then steps once to 0.150000 for every barrel above it.", "Shallow water, which charges 0.125000 up to 50000 bopd and steps to a higher tier past the threshold like deep offshore does.", "Frontier, which starts at 0.050000 and steps to 0.075000 once the field is producing at scale.", "Deep offshore, 0.050000 to 50000 bopd and 0.075000 past it."]'::jsonb, 3, 'Shallow water charges 0.125000 at every rate; the marginal field blends by rate and reads 0.062500 at 10000 bopd; frontier is 0.075000 throughout.'),
  ('cashflow', 'advanced', 'module', 'm06-the-expert-reading', 4, 'A field sells at a flat 80 USD per barrel for a decade. What does the PIA price royalty do over that decade?', '["It stays fixed at the 2021 rate of 0.030000, because a flat price meets the same anchor every year.", "It falls every year, because the anchors escalate at 2 percent a year from 2021: 80 USD pays 0.023908 in 2025 and 0.010630 in 2035.", "It rises with the field''s cumulative production, since the anchors are read on lifetime barrels rather than on the calendar.", "It falls only after 2030, when the 50 anchor escalates past 80 and the royalty switches off."]'::jsonb, 1, 'A flat price is a falling royalty; at 60 USD the royalty is gone by 2035 because the 50 anchor has escalated past it, and only the 0.100000 ceiling at 200 holds in every year.'),
  ('cashflow', 'advanced', 'module', 'm06-the-expert-reading', 5, 'AKATA''s NPV moves from 42943268.01 in shallow water to 141623594.88 in deep offshore under the conservative reading. Which two rates did the terrain string change?', '["The production royalty rate and the CIT rate, since CIT under the PIA is set by terrain and falls offshore.", "The production royalty rate and the development levy rate, which the 2025 framework sets lower for deep water.", "The production royalty rate, 0.125000 to 0.050000 on oil, and the HCT rate, 0.300000 to zero under the conservative reading.", "The price royalty rate and the HCT rate, because the price royalty anchors are set per terrain and deep offshore has the highest."]'::jsonb, 2, 'The aggressive reading keeps the HCT rate at 0.300000 and reports 61725382.46 with the same 59501441.00 of royalties; CIT stays 30 in every published case.'),
  ('cashflow', 'advanced', 'module', 'm06-the-expert-reading', 6, 'A reader checks every rate on AKATA under the PIA against the published tables, finds each one right, and reports 61725382.46 where 141623594.88 is the right answer. What went wrong?', '["One string, the deep offshore HCT reading, was read the other way; the strings are where the marks are lost, and no rate the reader typed was wrong.", "The reader used the 2021 price royalty anchors, which overstate the royalty and pull the NPV down by the difference.", "The reader ran the ledger on the nominal basis rather than the real one, and the 3 percent inflation accounts for the gap.", "The reader forgot the production allowance of 5500000.00 a year, which over the life is the difference between the two figures."]'::jsonb, 0, 'A fiscal ledger is worked from the outside in: regime, framework, terrain, then the bases; every rate can be right and the headline still wrong.'),
  ('cashflow', 'advanced', 'module', 'm06-the-expert-reading', 7, 'AKATA as a new lease with prior cumulative 0 and as a new lease with prior cumulative 96000000 print identical 2029 rows, allowance 17600000.00 on 2200000.00 eligible bbl with the cap flag false. How does a reader tell the two runs apart?', '["From the 2029 cap flag, which reads true on the prior-production run because the cap is tested on the prior barrels before the year begins.", "Only from the totals: the allowance is 77440000.00 over the life in one and 32000000.00 in the other, because the cap bites in later years.", "From the 2029 HCT, which is lower on the prior-production run because the allowance is prorated by the barrels left under the cap.", "They cannot be told apart at all, because the engine reports the allowance only for the first year and the totals are both 77440000.00."]'::jsonb, 1, 'HCT is 61048493.72 against 74680493.72 and NPV 55961597.02 against 46233118.46; a converted lease earns 5500000.00 in 2029 and 24200000.00 over the life.'),
  ('cashflow', 'advanced', 'module', 'm06-the-expert-reading', 8, 'On AKATA''s 2029 row under the PIA the CIT assessable profit is 134762247.64 and the chargeable profit 92762247.64. What is the 42000000.00 between them?', '["The production allowance of 5500000.00 plus the CPR deferral, which together reduce the CIT base before the rate is applied.", "The two-thirds restriction, which caps the chargeable profit at two thirds of the assessable one in every year.", "The HCT of 25422778.65 and the levy of 5390489.91, deducted from the CIT base together with the NDDC of 720000.00 because CIT is charged after them.", "The capital allowance, a fifth of the 210000000.00 capex over pia_capex_recovery_years 5."]'::jsonb, 3, 'CIT at 30 percent of 92762247.64 is 27828674.29; the production allowance never reaches CIT, and the restriction only acts where the allowance is large against a thin profit.'),
  ('cashflow', 'advanced', 'module', 'm06-the-expert-reading', 9, 'AKATA''s CPR cap binds in 2033, deferring 14561618.62, and the deferral clears in 2034. What would the same deferral have been if the ledger had ended in 2033?', '["A forfeiture: a deferred cost does not become a loss and does not survive cessation, so it would be reported as CPR forfeited and never claimed.", "A tax loss of 14561618.62 banked in hct_loss_carryforward and reported as tax losses unused at cessation.", "A refund, because a cap that binds in the final year is settled against the taxes already paid in earlier years.", "A claim in the final year, since the engine lifts the cap in the last row so that nothing is left on the table."]'::jsonb, 0, 'cpr_forfeiture defers 8000000.00 with no later year and ends with CPR forfeited at cessation 8000000.00; pia_cpr_carry_two_years forfeits 66000000.00 after three binding years.'),
  ('cashflow', 'advanced', 'module', 'm06-the-expert-reading', 10, 'The pre-submission checklist has a row for the final net cash flow. What does passing it look like?', '["The final flow is positive, because the engine refuses to report an IRR on a ledger whose last row is negative.", "The final flow matches the cumulative cash flow, which confirms that no row was dropped.", "The sign has been read: a negative final flow means the IRR beside it is one root of possibly two.", "The final flow has been discounted at the applied rate and added to the profile point at 6.8 percent, which must then equal the headline."]'::jsonb, 2, 'With the limit off a losing tail stays and hands the IRR a terminal negative; with a lump sum in 2035 AKATA ends on -29598201.95 and reports 23.2570 percent.'),
  ('cashflow', 'advanced', 'module', 'm06-the-expert-reading', 11, 'The engine holds both readings of deep offshore HCT, 141623594.88 and 61725382.46 on AKATA. Which does it choose?', '["The conservative one, which the digest records as conservative_zero and which is a finding of the extraction rather than a default.", "Neither: the choice belongs to counsel, and a ledger that reports one without the other has taken a legal position without saying so.", "The aggressive one, because the engine prefers the reading that collects more tax when the law is unsettled.", "The one that agrees with the terrain string, since deep offshore under the 2025 framework carries a fixed rate of 0.300000 in the table."]'::jsonb, 1, 'The engine models one reading of the law at a time; conservative_zero is a default somebody chose, not a finding.'),
  ('cashflow', 'advanced', 'module', 'm06-the-expert-reading', 12, 'A reader builds a distribution of AKATA''s NPV by rerunning the ledger across many price paths. What does the distribution inherit?', '["Every convention the ledger carries: basis, discounting convention, framework, terrain and reading, since the engine models one price path, one schedule and one working interest at a time.", "Nothing but the price range, because a probabilistic layer strips the fiscal conventions out of the runs it aggregates and reports a distribution that is free of convention, which is the whole point of building one.", "The IRR''s choice of root, which becomes a distribution of its own once Newton starts from 10 percent on every path, and which then replaces the NPV as the ranking measure because a rate needs no discount rate.", "A breakeven price, which the engine reports for each path and averages into the headline."]'::jsonb, 0, 'Ranges belong to the sweeps and to a probabilistic layer this course does not own; the price sweep from 82 to 120 moves NPV less than the terrain string does.'),
  ('cashflow', 'advanced', 'module', 'm06-the-expert-reading', 13, 'A buyer of AKATA asks what its unused loss pool, its forfeited CPR balance and its unclaimed depreciation are worth. What does the engine answer?', '["Their face value discounted at the applied rate, added to the NPV as a terminal value.", "The tax they would have saved at the marginal rate, which the KPI block reports as a deferred tax asset.", "The unclaimed depreciation only, which the ten-year default leaves unclaimed and reports as a residual asset at cessation.", "A memo line or silence: the engine stops at the last row, and the memo line is not in the NPV."]'::jsonb, 3, 'AKATA''s ten-year default straight line claims 174000000.00 of 255000000.00 capex in seven years, and the rest is neither banked, forfeited nor reported.'),
  ('cashflow', 'advanced', 'module', 'm06-the-expert-reading', 14, 'The same AKATA rows produced 72534830.66, 42943268.01, 141623594.88 and 61725382.46 without a barrel or a price changing. What changed between the four?', '["The discount rate, swept across the profile from 0 to 20 percent, with the four figures read at four of its points.", "The regime, the terrain string and the reading of the deep offshore HCT rule, and each figure is right for its question.", "The basis and the convention, since nominal against real and end-year against mid-year give four combinations.", "The working interest, stepped from 100 percent down through the published shares, with the PIA take invariant at 75.6789 percent across them."]'::jsonb, 1, '72534830.66 is JV terms, 42943268.01 the PIA in shallow water, 141623594.88 deep offshore conservative and 61725382.46 deep offshore aggressive; a number without its convention is not a number.'),
  ('cashflow', 'advanced', 'module', 'm06-the-expert-reading', 15, 'The ledger prices its levers in one currency. On AKATA under the PIA, what is a CPR cap of 40 percent worth?', '["The distance from 42943268.01 to 21471634.00, the same halving that a 50 percent working interest produces, since a cap on costs and a share of the field scale the ledger alike.", "Nothing on AKATA, because a cap of 40 percent of costs is above the costs claimed in every year, just as the worked example swept from 30 to 100 percent keeps 242500000.00 claimed at every setting.", "The distance from 42943268.01 to -1723561.25: the cap is a word in a document and it moves NPV further than the oil price sweep from 82 to 120 does.", "The distance from 42943268.01 to 36246417.05, the same move as taking the field onshore."]'::jsonb, 2, 'At 40 percent HCT rises from 77020493.72 to 107354738.83 and CIT from 86274711.53 to 117121931.63; the cap is a tax on the decline.'),
  ('cashflow', 'advanced', 'final', null, 1, 'psc_carryforward''s 2030 row carries 80000000.00 of capex and reports taxable income 27000000.00 and tax 13500000.00. Why is the year not a tax loss?', '["Because the 80000000.00 was depreciated over the ten-year default and only 8000000.00 of it reached the 2030 row as a deduction.", "Because the cost oil cap of 40 percent recovered the whole capex in 2030, leaving a profit to tax.", "Under a PSC the base is the contractor''s profit oil, and capex is not a deduction but a debt the cost oil repays.", "Because the royalty of 10000000.00 is credited against the loss under production sharing, which nets the year to a profit."]'::jsonb, 2, 'Cost oil of 36000000.00 came out of a pool that took in 80000000.00 of capex and 10000000.00 of opex; the rest is carried into 2031, which repeats every fiscal line.'),
  ('cashflow', 'advanced', 'final', null, 2, 'deriveOilRoyaltyRate reads 0.050000 for deep offshore at 50000 bopd and 0.075000 at 50001 bopd. On a deep offshore field lifting 60000 bopd, what rate do the barrels below the 50000 bopd threshold carry?', '["0.075000, like every other barrel of the year: the daily rate picks one rate for the whole year and nothing below the step is priced separately.", "0.050000, with 0.075000 charged on the 10000 bopd above the threshold, which is the blend the marginal field table shows across its tiers.", "0.050000 for the months before the field passed 50000 bopd and 0.075000 for the months after, read row by row from the production file.", "0.062500, the average of the two tiers, because the engine blends across a step in every terrain that has one."]'::jsonb, 0, 'pia_deep_offshore_full at 60000 bopd pays 131400000.00 on 1752000000.00 of gross revenue, 0.075000 of every barrel; the blend belongs to the marginal field alone, which reads 0.062500 at 10000 bopd.'),
  ('cashflow', 'advanced', 'final', null, 3, 'AKATA under the PIA prints hcdt 0.00 in 2029, 720000.00 in 2030 and 741600.00 in 2031, while nddc reads 720000.00 in 2029 and 741600.00 in 2030. Why do the two columns carry the same numbers one year apart?', '["NDDC is charged one year in arrears and HCDT in the current year, and the 2029 HCDT of 0.00 is a rounding of the first year''s fixed sum.", "The engine charges each levy on half the opex in alternate years, so the two columns take turns carrying the full 3 percent.", "Both read the current year''s opex, and the 2029 HCDT is 0.00 because the levy is suspended in the year of first oil under the 2025 framework.", "HCDT is 3 percent of the prior year''s opex and NDDC 3 percent of the current year''s, and AKATA set pia_prior_year_opex_usd to 0, so the first year pays no HCDT."]'::jsonb, 3, 'With a prior year opex of 20000000 the 2029 HCDT is 600000.00 and NPV moves from 42943268.01 to 42721818.62; neither levy is in the tax column.'),
  ('cashflow', 'advanced', 'final', null, 4, 'Under the 2021 Act the worked example pays TET of 25999871.36 and under the 2025 framework a development levy of 41599794.17, with royalty, HCT and CIT unchanged. Why does the digest call the levy 1.6 x TET?', '["The levy is charged on the HCT base, which is 15000000.00 larger because NDDC is not deducted from it.", "Same base, the CIT assessable profit of 1039994854.24; only the rates differ, 4 against 2.5.", "The levy is charged on the chargeable profit of 979994854.24 after the restriction, and then on the restricted amount again.", "The levy includes the TET it replaced plus the HCDT of 5100000.00 rolled into one line."]'::jsonb, 1, 'Total tax moves from 604809283.90 to 620409206.71 and NPV from 135185570.34 to 119585647.53; the rate is the smaller part of the difference, the base is where the money is.'),
  ('cashflow', 'advanced', 'final', null, 5, 'AKATA with a long tail to 2041 reports NPV 87727489.23 with the limit off and 93890737.45 with it on, limit year 2038, years trimmed 3. Why does the default hand a reader the lower figure?', '["The trimmed ledger is the optimistic one, and the engine defaults to the conservative reading that keeps every year the upload contains.", "The economic limit is off unless asked for, so the three years whose revenue less royalty falls short of opex stay in the ledger.", "The default trims on net cash flow rather than operating margin, and the three tail years still had positive net cash flow after tax.", "The limit is on by default but the KPI line only reports it when a year is trimmed, and 2039 to 2041 passed the test on their gross revenue."]'::jsonb, 1, '2038 passes, 37795328.32 against 31314556.41, and 2039 fails, 31541919.46 against 32253993.10; with the limit off the KPI line reads economic_limit_year not reported.'),
  ('cashflow', 'advanced', 'final', null, 6, 'A fiscal ledger is worked from the outside in. What is the order?', '["Headline first, then the rates that produce it, then the bases, so that every line reconciles to the NPV.", "Bases first, since the base decides more than the rate, then the rates, then the regime that names them.", "Regime, framework, terrain, then the bases, then the end of the ledger, and only then the headline.", "The end of the ledger first, because a terminal negative decides whether the IRR can be used, then the cascade."]'::jsonb, 2, 'Most wrong answers come from starting at the headline; get the framework wrong and every row''s last line is wrong.'),
  ('cashflow', 'advanced', 'final', null, 7, 'With the economic limit off, elt_off_tail_kept''s 2032 row sells 10000.00 bbl for 1000000.00 against 10000000.00 of opex, reports taxable income -14200000.00 and net cash flow -9200000.00. What two things does the kept row do to the ledger?', '["It banks a 14200000.00 loss with no year after it to spend it, and it hands the IRR a terminal negative that can have two roots or none.", "It relieves the 14200000.00 against the 2031 tax of 32500000.00 by carrying the loss back, and it lowers the IRR to 173.0447 percent by that relief.", "It forfeits the 14200000.00 as a CPR deferral and it forces the IRR to null, since a negative final row cannot bracket a root.", "It banks the loss for a year the engine appends automatically, and it raises the NPV from 13987603.31 by the relief in that year."]'::jsonb, 0, 'NPV is 13987603.31 with the row against 21590909.09 without it; the loss goes the way of jv_loss_unused_at_cessation''s 5000000.00, a memo line in no NPV.'),
  ('cashflow', 'advanced', 'final', null, 8, 'applyPSC on 100000000.00 of revenue with a 10 percent royalty and a 0.400000 cap recovers 36000000.00. Why not 40000000.00?', '["The cap is a share of the pool of 80000000.00 rather than of revenue, and 40 percent of the pool is what came out.", "The recovery is reduced by the contractor''s profit share of 50 percent applied to the cost oil as well as to the profit oil.", "The 4000000.00 shortfall is the tax on the cost oil, which the engine deducts before reporting the recovery.", "The cap is a share of revenue after royalty, not of the gross."]'::jsonb, 3, 'At 0.200000 the recovery is 18000000.00 and at 1.000000 it is the whole pool of 80000000.00, with profit oil moving down by the same steps as recovery moves up.'),
  ('cashflow', 'advanced', 'final', null, 9, 'The marginal field royalty reads 0.062500 at 10000 bopd, exactly halfway between 0.050000 and 0.075000, but 0.106250 at 20000 bopd, which is not halfway to 0.150000. Why the difference?', '["The rate is an average across the year''s barrels: at 10000 bopd the two lower tiers split the barrels evenly, and at 20000 the first 10000 bopd are still priced at those tiers while only the rest pays 15 percent.", "The 20000 bopd row has crossed the deep offshore step at 50000 bopd, which lifts the top tier to 0.075000 for the barrels above it.", "The blend uses a geometric mean above 10000 bopd and an arithmetic one below it.", "The 15 percent tier only opens at 50000 bopd, so at 20000 bopd the rate is still a blend of the two lower tiers weighted by revenue."]'::jsonb, 0, 'The marginal rate never reaches 0.150000; it approaches from below, reading 0.132500 at 50000 bopd and 0.142708 at 120000.'),
  ('cashflow', 'advanced', 'final', null, 10, 'cpr_forfeiture carries 40000000.00 of opex and 100000000.00 of capex over five recovery years against 80000000.00 of gross revenue, and prints cpr_cap 52000000.00. What is the 52000000.00 measured on?', '["The costs claimed: 65 percent of the opex plus the year''s fifth of the capex, so 52000000.00 is the most any year may recover and the rest becomes a tax loss.", "The gross revenue, at pia_cpr_limit_pct 65: a cap that is a share of revenue binds where costs approach revenue, and here it defers 8000000.00.", "The capex alone: the cap paces the 100000000.00 through the five recovery years, and opex is claimed outside it.", "The HCT assessable profit of 22987389.27, since the cap is a limit on deductions against profit rather than against revenue."]'::jsonb, 1, 'The worked example swept from 30 to 100 percent keeps 242500000.00 claimed at every setting because even 438000000.00 sits above the claim; the cap only exists where costs approach revenue, and the 8000000.00 deferred here is forfeited at cessation.'),
  ('cashflow', 'advanced', 'final', null, 11, 'pia_loss_relief has a 2025 base year and rows in 2025 and 2026. Its 2026 row prints pia_only and pays TET 5755415.35. What does that reveal about the date trigger?', '["It reads each row''s year, and 2026 is still inside the grace year the framework allows before the levy applies.", "It is disabled whenever a loss pool is being relieved, so the row stays under the framework the loss was banked in.", "It reads the base year, not the row year, and the framework chosen once is inherited by every row.", "It switched the framework but the TET column is where the engine prints the levy on a ledger that began under the Act."]'::jsonb, 2, 'A base year of 2026 on auto selects nta_2025 by the date alone, and a ledger based in 2026 would have paid the levy; the same holds on pia_cpr_carry_two_years, 2025 to 2027 all pia_only.'),
  ('cashflow', 'advanced', 'final', null, 12, 'AKATA with a 60000000 lump sum in 2035 reports NPV 38666394.86, IRR 23.2570 percent and total tax 148425219.46, and its 2035 net cash flow is -29598201.95. What about the 23.2570 must be read with the profile?', '["The IRR excludes the abandonment row, so 23.2570 is the rate of the six producing years and the profile carries the seventh.", "The rate was computed on the pre-tax flows because the lump sum is undeductible, so the profile on the post-tax flows sits lower.", "The rate is reported at four decimals while the profile point is at two, and the gap between them is the abandonment cost discounted.", "The final flow changed sign, so the rate is one root of a curve that may have another, and the engine does not warn."]'::jsonb, 3, 'At 200000000 the final flow is -169598201.95, the IRR is null and the NPV is negative at every sampled rate, -40359955.35 at the applied rate; the tax total never moves because the lump sum is post-tax.'),
  ('cashflow', 'advanced', 'final', null, 13, 'The engine models the conservative and aggressive readings of deep offshore HCT, 141623594.88 and 61725382.46 on AKATA, and will not choose. Who does?', '["The engine''s default, conservative_zero, which the digest records as a finding of the extraction.", "The terrain string, which carries the reading with it and settles the rate once the terrain is entered.", "The owner of the discount rate, since the two readings differ only in the rate at which the HCT is discounted.", "Counsel; a ledger that reports one without the other has taken a legal position without saying so."]'::jsonb, 3, 'The engine models one reading of the law at a time; conservative_zero is a default, not a finding.'),
  ('cashflow', 'advanced', 'final', null, 14, 'On cpr_forfeiture the CIT allowance the two-thirds restriction disallowed is not carried, cpr_deferred_to_next reads 8000000.00, and the ledger ends: CPR forfeited at cessation 8000000.00. Which of the unclaimed value on that row would a further year have rescued?', '["The CPR deferral only: it would have been claimed against the next year''s cap, while the disallowed allowance has no carryforward at all.", "The disallowed allowance only, which is deferred one year by the Act and claimed opex-first, while the CPR deferral is forfeited at the year end regardless.", "Both, since the engine carries every disallowed cost forward until the field stops.", "Neither, because a single-year field forfeits everything and a second year would start a fresh cascade with its own cap."]'::jsonb, 0, 'pia_cpr_carry_two_years carries 22000000.00, 44000000.00 and 66000000.00 across three binding years and forfeits the 66000000.00 at cessation; a tax loss would have survived as a number, and the PSC pool is never reported at all.'),
  ('cashflow', 'advanced', 'final', null, 15, 'AKATA under production sharing at a 45 percent cap recovers 75342960.00 in 2029 against 100457280.00 at 60 percent, and ends 2035 with 91570072.23 still in the pool where the 60 percent run ends with 0.00. Both runs put the same costs into the pool. What did the lower cap change?', '["How much went in: at 45 percent the engine adds the unrecovered profit oil to the pool, so the balance grows with every year the cap binds and never clears.", "Only how much may come out each year: the pool is the same money, the cap is a ceiling per year, and the years ran out before the 45 percent pool did.", "The share of the pool the contractor is entitled to, since the cap is a ceiling on the pool itself and 45 percent of it is all that may ever be recovered.", "The escalation of the balance, which the engine compounds at the 3 percent inflation rate while a pool waits and stops compounding once it clears."]'::jsonb, 1, 'The one-year applyPSC case says the same thing in miniature: 30000000 brought forward at the 0.4 cap still recovers 36000000.00 and only lifts the carried amount from 44000000.00 to 74000000.00; a bigger pool does not recover faster, it waits.'),
  ('cashflow', 'advanced', 'final', null, 16, 'The worked example sells at 80.000000 in 2025 and pays a price royalty of 34905145.759897 on 1460000000.00 of gross revenue. A reader prices it at the 2021 rate for 80 USD. What does the reader get?', '["The same figure, because the anchors are fixed by the 2021 Act and the escalator applies only to the price, not to the schedule.", "0.023908, because the 2021 table already carries the 2025 escalation for a field whose base year is 2025.", "0.030000 rather than the 0.023908 the engine applies, an overstated royalty and both tax bases downstream understated, with the error growing every year the field runs.", "0.050000, the rate at the 100 anchor, because the engine rounds the price up to the next anchor before reading the rate."]'::jsonb, 2, 'The anchor prices escalate at 2 percent a year from 2021, so the same nominal price earns a smaller rate every year: 80 USD reads 0.030000 in 2021, 0.023908 in 2025 and 0.010630 in 2035.'),
  ('cashflow', 'advanced', 'final', null, 17, 'A new shallow water lease with 1000000 bbl at 30 USD per barrel and no prior production earns an allowance of 6000000.00 rather than 8000000.00, and prod_alw_cap_applied reads false. Which rule cut the allowance, and what did the flag say about it?', '["The volume cap, read on lifetime barrels, which trimmed the eligible barrels; the flag reads false because a lease with no prior production has not yet reached 100000000 bbl.", "The 20 percent of price limit, which at 30 USD sits below the 8 USD new lease rate; the flag reports the volume cap only and stayed false.", "The converted lease rate of 2.5 USD per barrel, which the engine falls back to when the price is below the 50 anchor; the flag confirms that no cap of either kind acted.", "The two thirds restriction, which limits the allowance to two thirds of the assessable profit; the flag is false because that restriction is reported on the CIT line instead."]'::jsonb, 1, 'computeProductionAllowance prints cap applied false on every price-limited row, 2000000.00 on a converted lease at 10 USD as well; the flag is only ever true for a new lease that reaches its volume cap, 500000.00 eligible bbl from a prior 99500000.'),
  ('cashflow', 'advanced', 'final', null, 18, 'jv_loss_carryforward''s 2031 row reports taxable income 65000000.00, loss_offset_used 5000000.00 and tax 30000000.00. What is the tax charged on?', '["The taxable income column at a rate reduced by the loss, from 50 to a lower effective rate that the engine derives from the pool.", "Taxable income less depreciation of 5000000.00, deducted twice because 2030 had no revenue to absorb it.", "The cumulative cash flow, which is -10000000.00 at the end of 2031 and turns the tax into a partial refund.", "Taxable income less the offset; the offset has its own column and the taxable_income column does not show it being spent."]'::jsonb, 3, 'A reader checking the rate against the taxable income column concludes it is wrong; with relief off the row pays 32500000.00 and NPV falls from -13636363.64 to -15909090.91.'),
  ('cashflow', 'advanced', 'final', null, 19, 'AKATA''s fund from 2029 pays seven contributions of 8571428.57 and relieves the most tax, total 124585925.52, yet the fund from 2032, paying four of 15000000.00 with total tax 127157354.09, reports the higher NPV, 47415100.31 against 44902775.54. Why does the fund that relieves less tax score higher?', '["Its money leaves later, and later outflows cost less on present value than the extra relief the early fund earns is worth.", "Its contributions are fewer, and the engine charges each contribution a fee at the discount rate for every year it sits in the fund before the spend.", "Its total tax is higher, and take rewards a higher tax with a higher NPV because the pre-take value is measured after the fund has been paid.", "The early fund''s seven contributions are escalated at the 3 percent inflation rate while the four late ones are held at 15000000.00, so the early fund pays more in nominal money."]'::jsonb, 0, 'Both funds beat the lump sum''s 38666394.86 on NPV; on IRR the early fund reads 21.9086 percent against the lump sum''s 23.2570 and the late fund''s 23.9820, because money moved out of the early years hurts a rate more than a present value.'),
  ('cashflow', 'advanced', 'final', null, 20, 'The worked example forced to nta_2025 at a 2025 base year pays a levy of 41599794.17, and on auto at a 2026 base year 41684425.66. A reader attributes the whole difference to the framework. What actually moved the levy?', '["The framework: the levy rate is read from the base year, and a 2026 base year carries a slightly higher levy rate than a forced 2025 one.", "The discounting: a 2026 base year discounts the levy one year less, which the KPI line reports as the higher figure.", "Not the framework, which is nta_2025 both times, but the price royalty anchors, which escalated a year further and lowered the royalty to 215289358.59, raising the assessable profit the levy follows.", "The HCDT: a second year of opex history raises the prior-year levy and the assessable profit with it."]'::jsonb, 2, 'The price royalty falls from 34905145.759897 to 32789358.588134, HCT rises to 285445692.42 and CIT to 294633192.42, and NPV moves from 119585647.53 to 120347330.91.'),
  ('cashflow', 'advanced', 'final', null, 21, 'psc_tranches gives the contractor 60 percent from a cumulative of 0 and 40 percent from 1 million bbl. The 2030 row produces 1000000.00 bbl. Which share does 2030 carry?', '["60.000000, because the table is read at the cumulative liquids at the start of the year, and 2030 opens at 0.", "40.000000, because 2030''s own 1000000.00 bbl carries the field to the boundary and the share is read at the year''s end.", "50.000000, the average of the two tranches, because the field crosses the boundary on the last barrel of the year and the engine interpolates.", "60.000000 for the profit oil and 40.000000 for the cost oil, since the tranche table applies to both slices separately."]'::jsonb, 0, '999999 bbl gives 0.600000 and 1000000 gives 0.400000; 2030''s taxable income is 32400000.00 against 27000000.00 at a flat 50, and 2031 opens at 1000000 bbl and drops to 40.000000.'),
  ('cashflow', 'advanced', 'final', null, 22, 'AKATA''s 2029 row sells oil and gas for 186032000.00 of gross revenue at an oil price of 82.000000 and prints a price royalty of 3605512.362941. A reader who applies the year''s rate to the whole 186032000.00 lands above it. Which revenue does the price royalty charge?', '["The gross revenue less the production royalty of 22944240.00, which is the revenue after the first royalty and therefore the base of the second one.", "The oil and gas together, with the gas converted at 6 Mscf per barrel of oil equivalent and priced at the year''s oil price of 82.000000.", "The oil revenue alone: the price royalty reads the oil price and charges the oil, and the gas inside the gross revenue carries none of it.", "The revenue after HCDT and NDDC, since the levies come off before any royalty and the smaller base explains the smaller figure."]'::jsonb, 2, 'pia_gas_only_hct_zero has no oil and prints price_royalty 0.000000 beside a production royalty of 6300000.00 on 90000000.00 of gas revenue; on AKATA at 92.345318 in 2035 the price royalty is 1421137.383868 on 73325786.51, falling with the barrels because the anchors escalate at the same 2 percent as the price.'),
  ('cashflow', 'advanced', 'final', null, 23, 'pia_gas_only_hct_zero reports hct_assessable_profit 0.00 and NPV 17380000.00; with pia_hct_include_gas_revenue true the base becomes 68600000.00, HCT 19380000.00 and NPV -2000000.00. Which run reads the Act as the engine understands it?', '["The second: gas is a hydrocarbon and the default of excluding it is an omission the hatch corrects.", "The first: the hydrocarbon tax base is liquids, oil and condensate, with gas left out, and the hatch is a legacy escape that rebuilds the base on the whole revenue.", "Neither: gas carries its own HCT rate in the table, and both runs apply the liquids rate to it by mistake.", "Both, because the engine charges HCT on gas at 0.000000 in the first and at 0.300000 in the second, and the terrain decides which."]'::jsonb, 1, 'CIT is still 14880000.00 on a cit_chargeable_profit of 49600000.00 in both runs; on AKATA the gas revenue and its royalty are out of the HCT base of 130971072.31 and in the CIT base of 134762247.64.'),
  ('cashflow', 'advanced', 'final', null, 24, 'jv_loss_unused_at_cessation is one row, 2030, with 50000000.00 of capex, no production and a banked loss of 5000000.00, and its KPI line reads take null beside DPI -1.000000. Why is the take null rather than a percentage?', '["Because the unused loss of 5000000.00 is subtracted from the government''s share and leaves the ratio undefined until a later year spends it.", "Because take is only reported once payback has been reached, and a payback beyond project life leaves the ratio unreported on every single-row ledger the engine sees.", "Because a take is computed on the discounted flows, and a single row discounted at exponent zero has no discounting for the ratio to read, so the engine prints null.", "Take is the government share of a pre-take value, and with no revenue there is nothing to share, so the engine returns null rather than a percentage of nothing."]'::jsonb, 3, 'DPI -1.000000 is the honest reading: every unit of capital was lost. NPV is -50000000.00, the whole capex, and the 5000000.00 memo line appears nowhere in it; give the capex one more year of production and the pool is spent, tax 30000000.00 against 32500000.00.'),
  ('cashflow', 'advanced', 'final', null, 25, 'jv_abandonment_wi_60 charges the 10000000.00 lump sum in full against 60 percent flows, and pia_sinking_fund_wi_50 collects 15000000.00 against a 30000000.00 cost. What is abandonment_cost_usd under each funding mode?', '["A field-level number under both, scaled by the working interest on the way into the ledger.", "A share-level number under both, since the working interest is applied at the door to every input the row carries.", "A share-level number under a lump sum and a field-level one under a fund, and the engine does not say which.", "A field-level number under a lump sum and a share-level one under a fund, which is why the fund collects only half."]'::jsonb, 2, 'Distrust total_abandonment_cost as a statement of what the share paid: under a fund the share paid the contributions, under a lump sum it paid the whole 10000000.00.'),
  ('cashflow', 'advanced', 'final', null, 26, 'AKATA under the PIA is NPV 42943268.01. Write the sentence that names it.', '["42943268.01 at 10 percent nominal, mid-year, base year 2029, framework pia_only, shallow water, new lease.", "42943268.01 on the real basis, end-year, base year 2029, framework nta_2025, shallow water, converted PML, conservative reading.", "42943268.01 on the real basis, end-year, base year 2029, framework nta_2025, deep offshore, converted PML, aggressive reading.", "42943268.01 on the real basis, end-year, base year 2025, framework pia_only, shallow water, converted PML."]'::jsonb, 1, 'Every one of those words is a lever the ledger has shown moving: forced to pia_only the same rows report 49521778.87, and deep offshore conservative 141623594.88.'),
  ('cashflow', 'advanced', 'final', null, 27, 'pia_sinking_fund''s 30000000.00 contribution lowers HCT from 284810956.27 to 275810956.27 and CIT from 293998456.27 to 284998456.27 while TET stays 25999871.36. Which bases received the contribution?', '["The HCT chargeable profit and the CIT chargeable profit, each at its own rate; the levy base, the assessable profit, is untouched.", "The HCT base only, with the CIT change following because CIT is charged on the profit after HCT.", "All three bases, with the TET unchanged only because it is rounded to the nearest cent.", "The HCDT and NDDC lines, which are opex-based and so absorb an opex-lane contribution first."]'::jsonb, 0, 'The contribution rides the opex lane and relieves the two profit taxes at their rates and nothing else; NPV falls from 135185570.34 to 123185570.34.'),
  ('cashflow', 'advanced', 'final', null, 28, 'psc_itc sets a 50 percent credit on 80000000.00 of capex, and both years show tax 0.00 with taxable income 27000000.00 unchanged. What does the credit do that a deduction would not?', '["It is applied after the tax is computed and never touches the base; it absorbs the 13500000.00 of tax each year and the remainder carries unused past the end of the field with no refund.", "It reduces the taxable income to zero in both years, which is why the tax column reads 0.00 and the profit oil is unchanged.", "It is paid to the contractor as cash in 2030, which is why net cash flow rises from -40500000.00 to -27000000.00.", "It raises the cost oil cap by 50 percent so that the capex is recovered inside the two years."]'::jsonb, 0, 'The applyPSC sample shows the rule: an ITC of 40000000 against a tax before credit of 4500000.00 uses 4500000.00 and carries 35500000.00; the credit is not cash.'),
  ('cashflow', 'advanced', 'final', null, 29, 'pia_deep_offshore_wi_50 halves every monetary line and reports NPV 445282165.97, exactly half of 890564331.93, while pia_deep_offshore_naive_30k halves the upload instead and reports 372530915.97. Where does the naive run lose the difference?', '["It loses the production allowance, which the engine grants only above the 50000 bopd threshold.", "It is discounted for one more year because the smaller field is assumed to start later.", "It pays HCT at 0.300000, since the conservative reading only applies above the deep offshore threshold.", "At half the daily rate it falls into the 0.050000 tier, so its royalty is 43800000.00 rather than half of 131400000.00, and it still bears the full 100000000.00 of capex and opex and the full levies."]'::jsonb, 3, 'Two errors in opposite directions, and neither cancels the other: the royalty is understated and the costs overstated, and take reads 44.8919 percent against 42.6183.'),
  ('cashflow', 'advanced', 'final', null, 30, 'cpr_forfeiture has cit_assessable_profit 7987389.27, cit_chargeable_profit 2662463.09 and cit_tax 798738.93. Where does the allowance the two-thirds restriction disallowed reappear?', '["In cpr_deferred_to_next, which reads 8000000.00 and is the restricted allowance waiting for the next year.", "In hct_loss_carryforward, since the HCT on the same row is charged on 8487389.27 without the restriction and the difference is banked there.", "Nowhere: cit_loss_carryforward reads 0.00, and the disallowed amount has no carryforward in this engine, where the Act carries it.", "In the next year''s cit_loss_offset_used, where it is relieved against the first profit large enough to absorb it."]'::jsonb, 2, 'The 8000000.00 in cpr_deferred_to_next is the CPR cap''s deferral, a different mechanism; the chargeable profit is one third of the assessable profit because the allowance was capped at two thirds of it.'),
  ('cashflow', 'advanced', 'final', null, 31, 'With pia_apply_minimum_etr true at 85 percent the worked example''s total tax becomes 883995626.10, which is 85 percent of 1039994854.24, through a top-up of 279186342.20. Which taxes did the floor treat as already paid?', '["Only HCT and CIT, 284810956.27 plus 293998456.27, which is why the top-up is so large.", "HCT, CIT and TET, because royalty is charged on revenue and cannot count toward an effective rate on profit.", "All 604809283.90 of them, royalty and the levies included.", "Only the taxes on the chargeable profit of 979994854.24, the profit that the floor is measured against."]'::jsonb, 1, 'The 604809283.90 in the tax column is HCT 284810956.27 plus CIT 293998456.27 plus TET 25999871.36, with royalty 217405145.76, HCDT and NDDC outside it; test the floor against HCT plus CIT alone and the shortfall comes out larger than 279186342.20, and the top-up is charged on a profit measured before capex, so net cash flow becomes -144000771.86 and take 114.7315 percent.'),
  ('cashflow', 'advanced', 'final', null, 32, 'AKATA at a three-year shift has no 2031 row, and its IRR rises from 14.6753 to 15.1070 percent while NPV falls from 40880824.32 to 17894126.42. What does the rising IRR tell a reader?', '["That the delay improved the field, because the later rows sell at escalated prices of 87.019056 and beyond and the capex was shifted with them, so the 255000000.00 is a year cheaper on present value and the rate rises with it.", "That the engine emitted an empty 2031 row with zero flow and the extra row diluted the discounting, so the IRR and payback were computed over ten rows instead of nine and both moved in the field''s favour.", "That the loss pool of 21000000.00 was spent in the delayed first year and lifted the rate.", "That IRR and payback are counted on rows rather than calendar years, so the missing row made the delay look shorter to them; the NPV is discounted on calendar years and can be trusted."]'::jsonb, 3, 'A longer wait for the same money cannot raise a rate of return; capex is not shifted, and the engine refuses to emit a row for an empty year.'),
  ('cashflow', 'advanced', 'final', null, 33, 'psc_abandonment_wi_50 charges a 10000000.00 lump sum against 50 percent flows and reports a 2031 net cash flow of 9750000.00 where psc_wi_50 had 19750000.00; psc_sinking_fund instead shows a decom_fund_contribution of 10000000.00 in 2031. How do the two modes sit against the production sharing contract?', '["Both are paid outside the contract, and the fund is simply the lump sum spread over the years the contract has left, so the contribution of 10000000.00 in 2031 is charged after tax exactly as the lump sum on psc_abandonment_wi_50 is.", "The lump sum is paid outside the contract, unscaled after the working interest share, while the contribution enters the recoverable cost lane and rides the pool.", "Both enter the recoverable cost lane, and the lump sum is recovered as cost oil in the final year at the cap.", "The lump sum is scaled by the working interest at the door like every other PSC input, and the contribution is not, which is why the 50 percent case shows a net of 9750000.00 rather than a half-scaled outflow."]'::jsonb, 1, 'psc_sinking_fund''s 2031 net cash flow is 29500000.00 against 39500000.00 without it; under JV terms the same lump sum is unscaled too, 10000000.00 against 60 percent flows on jv_abandonment_wi_60.'),
  ('cashflow', 'advanced', 'final', null, 34, 'AKATA in deep offshore reports 61725382.46 under the aggressive reading and 141623594.88 under the conservative one, with royalties of 59501441.00 in both, against 42943268.01 in shallow water. How much of the conservative gain is royalty and how much is the hydrocarbon tax?', '["The royalty alone takes 42943268.01 to 61725382.46, since the aggressive reading keeps the HCT rate at 0.300000; the reading of the HCT rule takes it the rest of the way to 141623594.88.", "It is all royalty: the HCT rate is 0.000000 in deep offshore under either reading, and the two figures differ by the CIT the readings charge, since the aggressive reading moves the CIT rate rather than the HCT rate.", "It is all hydrocarbon tax: the production royalty is 0.125000 in every offshore terrain and only the price royalty moved, so the 59501441.00 of royalties in deep offshore is the shallow water figure less the price component alone.", "The two cannot be separated, because the terrain string sets one blended fiscal rate that the engine does not decompose."]'::jsonb, 0, 'The 2029 production royalty is 9301600.00 in deep offshore against 22944240.00 in shallow water, and HCT is 29481778.65 aggressive against 0.00 conservative; the terrain string moves NPV further than the price sweep from 82 to 120.'),
  ('cashflow', 'advanced', 'final', null, 35, 'AKATA under production sharing reports a take of 82.1085 percent at a 60 percent cost oil cap, at 80 and at 100, but 99.0577 at 45 and 120.4874 at 30. Why does the take stop moving above 60?', '["Above 60 percent the cap no longer binds in any year, so cost oil equals the year''s costs and the take is the royalty plus tax on a fixed profit oil.", "The engine caps the take at 82.1085 percent for production sharing, which is the royalty rate plus the tax rate blended at the contractor share.", "Once the pool clears inside the field''s life the cap only moves timing, and timing is what NPV and IRR price, not take.", "Above 60 percent the contractor share of profit oil steps down to hold the take constant, as the tranche mode requires once the pool has cleared."]'::jsonb, 2, 'At 60 percent the pool clears in 2034, at 80 in 2031 and at 100 in 2030; NPV still rises from 29960298.75 to 48148675.31 across the three because the money arrives sooner.'),
  ('cashflow', 'advanced', 'final', null, 36, 'AKATA run as a marginal field cuts the 2029 production royalty from 22944240.00 to 10182990.00 but reports HCT of 29251153.65 against 25422778.65, and NPV 61154067.34 rather than a larger gain. Why did the tax take most of the royalty back?', '["The marginal blend charges the shortfall in royalty as HCT, since the two are reconciled at the end of the cascade.", "The marginal field pays the price royalty at the top tier, and the price royalty is charged inside the HCT column.", "The marginal terrain carries the highest gas royalty, and AKATA''s associated gas makes up the difference.", "The pre-2021 flag was not set, so the field pays HCT at 30 percent on a base the smaller royalty has left larger."]'::jsonb, 3, 'pia_marginal_field_blend sets the flag and pays 0.150000, 26361776.50 on 175745176.68; the blend does not switch the tax rate, the flag does.'),
  ('cashflow', 'advanced', 'final', null, 37, 'AKATA under the PIA claims 66000000.00 against a cpr_cap of 120920800.00 in 2029, its 24000000.00 of opex plus a fifth of the 210000000.00 capex, and 75720000.00 against 103717068.00 in 2030 beside opex of 24720000.00. Why did the claim grow by more than the opex did?', '["The 45000000.00 of capex spent in 2030 started its own five-year recovery, so 2030 claims a fifth of both tranches beside its opex.", "The 2029 allowance was restricted to two thirds of the assessable profit and the disallowed third was carried into the 2030 claim, as the Act requires it to be.", "The cap fell from 120920800.00 to 103717068.00, and the engine claims the whole gap between cap and opex in any year the cap falls, so a lower cap raises the claim.", "The production allowance of 4625000.00 is claimed inside the CPR claim from the second year onward, and its arrival is the extra in 2030."]'::jsonb, 0, 'On the worked example the recovery years are the whole answer, 482500000.00 claimed at 1 and 212500000.00 at 10 against 242500000.00 at 5; on AKATA each tranche runs its own clock, and a field that stops before the years run out never claims the rest.'),
  ('cashflow', 'advanced', 'final', null, 38, 'On the real basis AKATA''s profile point labelled 6.8 reads 72513070.98 against a headline of 72534830.66, and on multiyear_pia_real the gap is -40996.42. Why is the gap always negative?', '["The profile uses the nominal flows and the headline the real ones, and the nominal flows are always larger.", "The point is evaluated at the applied rate rounded to two decimals, 6.8 sits past 6.796117, and NPV falls with rate.", "The profile is summed after each row is rounded down to the cent, and rounding down can only lower a sum.", "The profile discounts the base year row once and the headline does not, which removes a small amount at every rate on the real basis."]'::jsonb, 1, 'On the nominal basis the applied point matches the headline exactly, 21590909.09 on jv_analytic_decision_kpis; the engine''s own npv() at the exact rate returns 72534830.66.'),
  ('cashflow', 'advanced', 'final', null, 39, 'AKATA on auto reports 42943268.01 with a levy of 5390489.91 in 2029; forced to pia_only it reports 49521778.87 with TET of 3369056.19. A reader writes 42943268.01 beside the word pia_only. What does the checklist say?', '["The headline passes, because the framework only changes the last line of the cascade and the NPV is reported before the levy is charged.", "The headline passes if the override was left on auto, since auto is neither framework and the label is a matter of convention.", "The headline fails: basis, convention and framework are written beside it, and 42943268.01 belongs to nta_2025.", "The headline fails only by the levy: subtract 21007007.79 and add 3369056.19 to move it to the pia_only figure, since the two frameworks share every other line."]'::jsonb, 2, 'Get the framework wrong and every row''s last line is wrong; one of tet_tax and dev_levy_tax is 0.00 on every row and the fiscal_framework column says which.'),
  ('cashflow', 'advanced', 'final', null, 40, 'AKATA with a 200000000 lump sum reports IRR null while its NPV is -40359955.35 at the applied rate and -58362170.82 at 0 percent. The checklist asks for the sign of the final flow. What does the reader conclude?', '["The null is a root finder fault, since a project with a defined NPV at every rate must have a rate that zeroes it.", "The final flow is negative, so the IRR is the lower of two roots and the engine printed null in place of the smaller one, which the bisection fallback cannot reach from 10 percent because the NPV never changes sign in the region it searches.", "The null means the field is worth exactly its capex at every rate, which the negative profile then contradicts, so the ledger is refused and the NPV figures printed beside it are the ones from the run without the abandonment.", "The final flow of -169598201.95 is negative, so no IRR on this ledger could be trusted on its own; the profile, negative at every sampled rate, is the reading, and null is not a data error."]'::jsonb, 3, 'With 60000000 the final flow is -29598201.95 and the engine reports 23.2570 percent, one root of a curve that may have another; the engine refuses to warn that the final flow changed sign.'),
  ('cashflow', 'advanced', 'final', null, 41, 'The 2029 row of AKATA as a new lease is identical whether the prior cumulative is 0 or 96000000: allowance 17600000.00, cap applied false, HCT 21792778.65. Which reading in the working order catches the difference before the headline does?', '["The lease and reading step, followed by the totals: allowance 77440000.00 against 32000000.00 over the life, since the cap bites in later years.", "The framework step, since a lease with prior production is read under pia_only and one without under nta_2025.", "The 2029 row alone, whose cap applied flag reads true once the prior barrels are entered.", "The royalty step, because prior production lifts the field into the 0.075000 tier and the royalty totals differ, so the difference is in the royalty line rather than in the allowance."]'::jsonb, 0, 'NPV is 55961597.02 against 46233118.46 and HCT 61048493.72 against 74680493.72; the strings must be read from the case, not guessed from a rule of thumb.'),
  ('cashflow', 'advanced', 'final', null, 42, 'psc_wi_50 halves oil_bbl to 500000.00 a year and reports total oil 1000000.00 bbl, while pia_deep_offshore_wi_50 halves oil_bbl to 10950000.00 but keeps cumulative_oil_bbl_lifetime at 21900000.00. Which ledger still remembers the field?', '["The PSC one: entitlement volumes are the field''s volumes scaled, and the tranche table is read on the field''s cumulative rather than the entitlement, so a 50 percent share still opens each year at the field''s tranche boundary.", "The PIA one: the working interest is applied to the money afterward, and cumulative_oil_bbl_lifetime and prod_alw_eligible_bbl keep the field''s barrels so the tier is read at 60000 bopd.", "Both, since each reports working_interest_pct and the engine can recover the field from a share when that column is set.", "Neither, because a scaled run has no field-level readout in either regime and the naive upload cannot be told from a small field."]'::jsonb, 1, 'Under a PSC the working interest is applied at the door and the rows are the share; under the PIA the royalty is still 0.075000 and half of 131400000.00 is 65700000.00, with take invariant at 42.6183 percent.');
